((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).en = window.CARDS_BY_LANG.en || {}).series = [{"name":"Game of Thrones","emoji":"🐉","meta":["drama, fantasy","2011–2019","USA"],"description":"An epic adaptation of George R. R. Martin's novels about the noble houses of Westeros fighting over the Iron Throne. HBO wove together political scheming, huge battles and a mythology of dragons and the threat beyond the Wall. At its peak the show pulled tens of millions of viewers worldwide.","fact":"The final season triggered a wave of petitions from disappointed viewers demanding that the ending be reshot from scratch.","wiki_en":"Game of Thrones"},{"name":"Breaking Bad","emoji":"🧪","meta":["drama, crime","2008–2013","USA"],"description":"A high-school chemistry teacher gets a cancer diagnosis, starts cooking methamphetamine to provide for his family, and turns step by step into a ruthless crime boss. The show is famous for its tight plotting and the slow rebirth of its main character.","fact":"Creator Vince Gilligan pitched the idea as turning Mr. Chips into Scarface.","wiki_en":"Breaking Bad"},{"name":"Friends","emoji":"☕","meta":["sitcom","1994–2004","USA"],"description":"Six friends live around the corner from one another in New York and go through jobs, relationships and growing up together. Most of the action plays out in their apartments and in Central Perk, the coffee house that became one of the most recognisable places on television.","fact":"The cast insisted on being paid equally, and in the later seasons each of them earned a million dollars per episode.","wiki_en":"Friends"},{"name":"The Office","emoji":"📎","meta":["mockumentary, comedy","2005–2013","USA"],"description":"The American take on a British sitcom, shot as a fake documentary about the working days of the staff at Dunder Mifflin, a paper company in a small town. A camera crew is supposedly filming them, and the characters keep talking straight into the lens.","fact":"It started as an almost line-for-line remake of the British original, but from the second season it found its own tone and became a phenomenon in its own right.","wiki_en":"The Office (American TV series)"},{"name":"The Simpsons","emoji":"🍩","meta":["animated series, comedy","since 1989","USA"],"description":"A yellow-skinned family from the fictional town of Springfield is the vehicle for a running satire on American life, pop culture and politics. It has been on the air longer than any other prime-time series in the history of American television.","fact":"Plenty of Simpsons plot twists later came true in real life, which spawned a whole internet myth about the show predicting the future.","wiki_en":"The Simpsons"},{"name":"South Park","emoji":"🏔️","meta":["animated series, comedy","since 1997","USA"],"description":"A scandal-magnet cartoon about four boys in a small mountain town in Colorado that goes after the week's news and society's taboos with almost no filter. Episodes are often written and edited just days before they air so the show can keep up with the headlines.","fact":"Kenny, one of the four leads, dies in nearly every episode of the early seasons and always turns up alive and well in the next one.","wiki_en":"South Park"},{"name":"Family Guy","emoji":"🐶","meta":["animated series, comedy","since 1999","USA"],"description":"A cartoon about the absurd Griffin family in the fictional town of Quahog, where the plot keeps breaking off into nonsensical digressions and parody flashbacks. Creator Seth MacFarlane voices several of the main characters himself, including Brian the talking dog.","fact":"Cancelled for low ratings in the early 2000s, it was brought back on air largely thanks to the wild popularity of its reruns and DVD sales.","wiki_en":"Family Guy"},{"name":"Rick and Morty","emoji":"🌀","meta":["animated series, science fiction","since 2013","USA"],"description":"A cartoon about Rick, a brilliant, cynical, hard-drinking scientist, and Morty, his anxious grandson, who travel between countless dimensions and worlds. Under the layer of manic humour and science fiction sit questions about the point of existence and about family.","fact":"Rick's battle cry \"Wubba lubba dub dub\" is translated by his friend Birdperson as something far sadder: \"I am in great pain, please help me.\"","wiki_en":"Rick and Morty"},{"name":"Futurama","emoji":"🚀","meta":["animated series, science fiction","since 1999, with gaps","USA"],"description":"From Simpsons creator Matt Groening: delivery boy Fry is frozen in a cryogenic pod in 1999 and wakes up a thousand years later in a bizarre future. Together with the crew of a delivery spaceship he ends up in adventures across the galaxy.","fact":"Despite several cancellations and shutdowns, the show kept coming back through films, new seasons and streaming revivals.","wiki_en":"Futurama"},{"name":"Stranger Things","emoji":"💡","meta":["science fiction, horror","since 2016","USA"],"description":"A story steeped in eighties nostalgia about a group of teenagers in the small town of Hawkins, where a boy goes missing and supernatural events begin. The show braids adolescent friendship together with the mythology of a parallel world, the Upside Down.","fact":"It turned a cast of near-unknown child actors into stars and put Winona Ryder, a film star of the 1990s, back in the spotlight.","wiki_en":"Stranger Things"},{"name":"The Sopranos","emoji":"🍝","meta":["drama, crime","1999–2007","USA"],"description":"A New Jersey Italian-American mob boss runs his criminal business while sitting through sessions with a psychotherapist, trying to get his panic attacks under control. The show largely set the standard for modern prestige television drama.","fact":"The closing scene in a diner, which cuts to sudden black in the middle of a song, is still argued about today.","wiki_en":"The Sopranos"},{"name":"The Wire","emoji":"🎧","meta":["drama, crime","2002–2008","USA"],"description":"A many-layered drama about Baltimore that starts with a wiretap on drug dealers and ends up showing the whole city, from police and dockworkers to schools, politicians and the press. Each season shifts its focus to another institution of urban life.","fact":"It won no Emmy at all during its original run, although critics regularly name it one of the best shows in the history of television.","wiki_en":"The Wire"},{"name":"Sherlock","emoji":"🔍","meta":["detective, drama","2010–2017","United Kingdom"],"description":"A modern British reading of Arthur Conan Doyle, with Sherlock Holmes and Doctor Watson working in today's London, smartphones and social media in place of telegrams. The show is known for its breakneck pace and for putting the detective's train of thought right on screen.","fact":"Because of its stars' schedules the show comes in very short seasons of three feature-length episodes, and the gaps between them stretched into years.","wiki_en":"Sherlock (TV series)"},{"name":"House","emoji":"🩺","meta":["drama","2004–2012","USA"],"description":"A medical drama about Doctor House, a brilliant and thoroughly unpleasant diagnostician who, with his team, untangles the rarest and most baffling cases. He is famous for his cynical one-liners and for his rule that patients always lie.","fact":"The creators modelled House openly on Sherlock Holmes, right down to the flat number and the loyal friend at his side.","wiki_en":"House (TV series)"},{"name":"Lost","emoji":"🏝️","meta":["drama, science fiction","2004–2010","USA"],"description":"A plane goes down and the surviving passengers wash up on a mysterious tropical island where inexplicable things happen. The show mixes the drama between its characters with an island mythology that unfolds through flashbacks.","fact":"It was among the first shows to make non-linear flashbacks and flash-forwards a main storytelling device on television.","wiki_en":"Lost (TV series)"},{"name":"Prison Break","emoji":"⛓️","meta":["drama, thriller","2005–2009","USA"],"description":"Engineer Michael Scofield commits a crime on purpose to get himself into the prison where his brother is serving a sentence he does not deserve, the escape plan tattooed across his own body. The show is built around the tense preparation and execution of an audacious jailbreak.","fact":"The huge map tattoo was not inked on the actor: the make-up team applied it in transfers, a process that took several hours each time.","wiki_en":"Prison Break"},{"name":"Dexter","emoji":"🔪","meta":["drama, thriller","2006–2013","USA"],"description":"Blood-spatter analyst Dexter Morgan helps the Miami police solve murders by day and commits his own by night, killing criminals according to the strict code his foster father taught him. The show runs on his voice-over musings about his double life.","fact":"The lead is Michael C. Hall, until then known for another unusual series about death, Six Feet Under.","wiki_en":"Dexter (TV series)"},{"name":"The Walking Dead","emoji":"🧟","meta":["horror, drama","2010–2022","USA"],"description":"Adapted from the comics: sheriff Rick Grimes comes out of a coma into a world overrun by a zombie epidemic and gathers a group of survivors around him. As the series goes on, the focus shifts from the zombies to the clashes between rival groups of humans.","fact":"For years it was the most watched show on American cable television among viewers under 49.","wiki_en":"The Walking Dead (TV series)"},{"name":"The Big Bang Theory","emoji":"🤓","meta":["sitcom","2007–2019","USA"],"description":"A sitcom about a group of Caltech physicists whose lives revolve around science, comics and video games, until a pretty waitress named Penny moves in across the hall. The humour comes from the gap between their brilliance in the lab and their awkwardness with people.","fact":"To keep things accurate, the formulas on the whiteboards were written by a consultant, a physicist from the University of California.","wiki_en":"The Big Bang Theory"},{"name":"How I Met Your Mother","emoji":"☂️","meta":["sitcom","2005–2014","USA"],"description":"Ted Mosby, speaking from the future, tells his children the long, tangled story of how he met their mother, recalling years of friendship, love and misadventure with four close friends in New York. The eccentric, charming Barney is the group's wild card.","fact":"The mother herself is not seen until the end of the eighth season; until then she is hinted at through details like a yellow umbrella.","wiki_en":"How I Met Your Mother"},{"name":"Scrubs","emoji":"🏥","meta":["sitcom","2001–2010","USA"],"description":"A comedy about the daily grind of young doctor J.D. at the fictional Sacred Heart hospital, where absurd humour sits next to unexpectedly serious and moving medical storylines. A good share of the jokes come from the hero's daydreams, which the viewer sees on screen.","fact":"Many of the storylines came from real cases that a doctor working as a consultant on the show told the writers about.","wiki_en":"Scrubs (TV series)"},{"name":"Sex and the City","emoji":"👠","meta":["comedy, drama","1998–2004","USA"],"description":"Columnist Carrie Bradshaw and three close friends live full, noisy lives in New York, talking through love, careers and sex over Cosmopolitans. Each episode is built around the column Carrie is writing about modern relationships.","fact":"The characters' wardrobe, the famous Manolo Blahnik shoes included, became a substantial part of the show's cultural legacy.","wiki_en":"Sex and the City"},{"name":"Desperate Housewives","emoji":"🏡","meta":["drama, comedy","2004–2012","USA"],"description":"Life among several housewives on the quiet street of Wisteria Lane, full of secrets, affairs and crimes, seen through the eyes of a neighbour who kills herself in the first episode and narrates everything from beyond. Soap opera crossed with black comedy and mystery.","fact":"The creator got the idea after watching a news report about a mother who had drowned her own children.","wiki_en":"Desperate Housewives"},{"name":"Gossip Girl","emoji":"💌","meta":["drama","2007–2012","USA"],"description":"The lives of spoiled teenagers on Manhattan's Upper East Side, told through the anonymous posts of a mysterious gossip blogger who knows every secret, betrayal and scandal among the privileged young. Her voice-over runs through every episode.","fact":"Gossip Girl's narration is voiced by actress Kristen Bell, and the blogger's identity is only revealed in the final episode.","wiki_en":"Gossip Girl"},{"name":"Grey's Anatomy","emoji":"❤️‍🩹","meta":["drama","since 2005","USA"],"description":"A medical drama about the surgical residents at Seattle Grace hospital, whose working lives are inseparable from their tangled private ones and from romances with each other. Known for Meredith Grey's voice-over, it became one of the longest-running American dramas.","fact":"The title plays on an old anatomy textbook that generations of doctors have learned from.","wiki_en":"Grey's Anatomy"},{"name":"The X-Files","emoji":"👽","meta":["science fiction, detective","1993–2018","USA"],"description":"FBI agents Mulder and Scully investigate cases involving the paranormal, aliens and government conspiracies: he believes in the inexplicable, while his sceptical partner looks for rational explanations. The show largely defined the supernatural TV mystery of the nineties.","fact":"Its tagline \"The truth is out there\" became a catchphrase far beyond television.","wiki_en":"The X-Files"},{"name":"Twin Peaks","emoji":"🪵","meta":["detective, mystery","1990–1991","USA"],"description":"The investigation into the murder of schoolgirl Laura Palmer brings FBI agent Dale Cooper to the small town of Twin Peaks, where surreal secrets and otherworldly forces hide behind a cosy provincial front. David Lynch fused a murder mystery with the atmosphere of a dream.","fact":"The line \"The owls are not what they seem\" became one of the main emblems of the show's enigmatic mythology.","wiki_en":"Twin Peaks"},{"name":"True Detective","emoji":"🥃","meta":["detective, drama","since 2014","USA"],"description":"An anthology in which every season tells its own bleak crime story with new characters and a new cast. The first and best known follows two detective partners who spend nearly twenty years on a string of ritual murders in Louisiana.","fact":"A six-minute sequence in the fourth episode of season one was shot in a single unbroken take and became one of the most talked-about scenes on television.","wiki_en":"True Detective"},{"name":"Black Mirror","emoji":"📱","meta":["science fiction, drama","since 2011","United Kingdom"],"description":"An anthology in which nearly every episode is a self-contained, bleak parable about the way modern technology can warp human relationships and whole societies. The title points at the dark screen of a gadget that we stare into as if into a mirror.","fact":"One instalment, Bandersnatch, was an interactive film in which the viewer chose how the story went.","wiki_en":"Black Mirror"},{"name":"Peaky Blinders","emoji":"🎩","meta":["drama, crime","2013–2022","United Kingdom"],"description":"The Shelby family of Birmingham builds its own criminal empire after the First World War under the charismatic, calculating Thomas Shelby. The name comes from a legend that the gang sewed razor blades into the peaks of their caps.","fact":"Although the action is set in the early twentieth century, the soundtrack is built almost entirely on modern rock and electronic music.","wiki_en":"Peaky Blinders"},{"name":"Vikings","emoji":"⚔️","meta":["drama, history","2013–2020","Canada"],"description":"The half-legendary story of the Scandinavian chieftain Ragnar Lothbrok, who leads his people on bold sea raids into Western Europe. The show leans loosely on the Norse sagas and chronicles, blending historical events with mythology.","fact":"For period flavour many lines are spoken in Old Norse and Old English with subtitles.","wiki_en":"Vikings (2013 TV series)"},{"name":"The Witcher","emoji":"🐺","meta":["fantasy, drama","since 2019","USA"],"description":"Adapted from Andrzej Sapkowski's books about Geralt of Rivia, a witcher who hunts monsters for hire and whose path becomes entangled with those of the sorceress Yennefer and the princess Ciri. Dark fantasy laced with the scheming of warring kingdoms.","fact":"Henry Cavill is a big fan of the books and games, and played the part in a white wig and yellow contact lenses.","wiki_en":"The Witcher (TV series)"},{"name":"The Mandalorian","emoji":"🪖","meta":["science fiction","since 2019","USA"],"description":"A lone bounty hunter in steel armour from the Star Wars universe takes a mysterious infant of his own kind under his protection and sets off on a dangerous journey through the edges of the galaxy. The show brought the spirit of the western back to a familiar saga.","fact":"The studio never officially named the cute green child that fans nicknamed \"Baby Yoda\" until the second season.","wiki_en":"The Mandalorian"},{"name":"The Last of Us","emoji":"🍄","meta":["drama, horror","since 2023","USA"],"description":"Adapted from the video game: smuggler Joel agrees to escort Ellie, a teenage girl who may hold the key to saving humanity, across an America laid waste by a fungal pandemic. The show cares about the bond between the two as much as about surviving the infected.","fact":"Much of the script was written by the creators of the original game, which let the plot and the characters carry over almost unchanged.","wiki_en":"The Last of Us (TV series)"},{"name":"Chernobyl","emoji":"☢️","meta":["drama, history","2019","USA, United Kingdom"],"description":"A miniseries about the 1986 disaster at the Chernobyl nuclear power plant and what it did to the clean-up workers, the scientists and the people of the towns nearby. The makers rebuilt Soviet daily life and the mood of the era with enormous attention to detail.","fact":"Many of the interiors and streets were recreated in Lithuania, where Soviet architecture in a similar style has survived.","wiki_en":"Chernobyl (miniseries)"},{"name":"The Crown","emoji":"👑","meta":["drama, history","2016–2023","United Kingdom"],"description":"A drama that follows Queen Elizabeth II and her family from her accession in the early fifties to recent decades, showing the monarchy backstage against a run of great historical events. Every few seasons the main cast is replaced wholesale so the actors match the characters' ages.","fact":"For accuracy the team rebuilt costumes and interiors from archive photographs and genuine royal outfits.","wiki_en":"The Crown (TV series)"},{"name":"Money Heist","emoji":"🎭","meta":["drama, crime","2017–2021","Spain"],"description":"A crew led by the enigmatic Professor seizes the Royal Mint of Spain in order to print billions of euros from inside rather than steal them. Every member takes the name of a city, and the Salvador Dalí masks became the show's calling card.","fact":"The Spanish series became one of the most watched non-English-language titles on Netflix anywhere in the world.","wiki_en":"Money Heist"},{"name":"Squid Game","emoji":"🦑","meta":["drama, thriller","2021","South Korea"],"description":"Hundreds of people drowning in debt agree to take part in a run of deadly children's games for an enormous cash prize. The contest is secretly watched by wealthy spectators, for whom other people's desperation is entertainment.","fact":"On release it became the most watched title in the entire history of Netflix.","wiki_en":"Squid Game"},{"name":"Narcos","emoji":"🌿","meta":["drama, crime","2015–2017","USA"],"description":"A reconstruction of the war between the Colombian drug cartels and American government agents, centred on the rise and fall of the notorious drug lord Pablo Escobar. The narration mixes documentary archive footage with dramatised scenes.","fact":"Part of the series was shot in Colombia itself, and some of the locations are tied to real events in the cartel's history.","wiki_en":"Narcos"},{"name":"Ozark","emoji":"💵","meta":["drama, crime","2017–2022","USA"],"description":"Financial adviser Marty Byrde has to move his family to the Ozark holiday region and launder money for a Mexican drug cartel to clear his debts. The show tracks how an outwardly comfortable family sinks step by step into the criminal world.","fact":"The title refers to the real Ozark region on the Missouri–Arkansas border, where almost all of the story takes place.","wiki_en":"Ozark (TV series)"},{"name":"Better Call Saul","emoji":"⚖️","meta":["drama, crime","2015–2022","USA"],"description":"This prequel to Breaking Bad tells the story of lawyer Jimmy McGill and his gradual turn into the slippery hustler Saul Goodman. It traces his moral collapse in fine detail, long before the events of the parent show.","fact":"Plenty of critics call the prequel the equal of Breaking Bad as drama, and some rate it higher than the original.","wiki_en":"Better Call Saul"},{"name":"Mad Men","emoji":"🥃","meta":["drama","2007–2015","USA"],"description":"A drama about the staff of an advertising agency on New York's Madison Avenue in the early sixties, centred on Don Draper, a charismatic creative director who lets nobody in. The show is famous for its painstaking recreation of the fashion, interiors and manners of the era.","fact":"According to its makers, \"mad men\" was the slang nickname that Madison Avenue advertising people used for themselves.","wiki_en":"Mad Men"},{"name":"House of Cards","emoji":"🃏","meta":["drama","2013–2018","USA"],"description":"Passed over for the post he was promised, cynical congressman Frank Underwood launches a merciless campaign of scheming to climb to the summit of American power, turning to speak straight to the viewer along the way. It was one of Netflix's first big original productions.","fact":"The American version is a remake of a British miniseries from 1990, based on the novel by Michael Dobbs.","wiki_en":"House of Cards (American TV series)"},{"name":"Succession","emoji":"💼","meta":["drama, black comedy","2018–2023","USA"],"description":"A satirical drama about media mogul Logan Roy and his grown children, who plot and tear at each other for the right to inherit his global media empire. It skewers the manners of the ultra-rich and the corporate fight for power.","fact":"The writing draws heavily on real media dynasties, though the creators always insisted the characters are invented.","wiki_en":"Succession (TV series)"},{"name":"The White Lotus","emoji":"🌺","meta":["black comedy, drama","since 2021","USA"],"description":"An anthology in which every season unfolds at another luxury hotel of the White Lotus chain and follows guests and staff whose hidden vices and grudges gradually surface. From the first minutes of a season the viewer knows that one of them will end up dead.","fact":"The first season was shot in Hawaii at a working resort hotel, where the entire crew also lived during the production.","wiki_en":"The White Lotus"},{"name":"Euphoria","emoji":"💊","meta":["drama","since 2019","USA"],"description":"The lives of a group of American high-school students seen through addiction, the search for identity and first love, told with bold visual flourishes and the voice-over of its heroine Rue. The addiction storyline is handled with nothing softened.","fact":"The bright glitter make-up worn by the show's characters set off a fashion trend of its own, complete with its own name.","wiki_en":"Euphoria (American TV series)"},{"name":"Wednesday","emoji":"🖤","meta":["comedy, horror","since 2022","USA"],"description":"Wednesday, daughter of the Addams family, enrols at Nevermore, a gloomy academy for outcasts, where she has to unravel a supernatural mystery, make the first friends of her life and get to grips with her own paranormal gifts. Gothic style crossed with teen comedy.","fact":"The dance she performs at the school ball was largely invented by the actress herself and went viral on social media worldwide.","wiki_en":"Wednesday (TV series)"},{"name":"Bridgerton","emoji":"💍","meta":["drama, romance","since 2020","USA"],"description":"Adapted from Julia Quinn's novels about the large Bridgerton family in Regency London high society, with each season built around the love story of one of the siblings. The scandals and rumours of society are tracked from the shadows by the anonymous gossip writer Lady Whistledown.","fact":"Unlike the classic costume drama, the show is pointedly multiracial in its casting, which became a much-discussed choice.","wiki_en":"Bridgerton"},{"name":"The Queen's Gambit","emoji":"♟️","meta":["drama","2020","USA"],"description":"A miniseries about young chess prodigy Beth Harmon, who grows up in an orphanage, struggles with a tranquilliser addiction and works her way to the summit of a largely male chess world. Its chess games are staged as tensely as any sporting duel.","fact":"After it aired, interest in chess shot up around the world, from sales of chessboards to sign-ups for lessons.","wiki_en":"The Queen's Gambit (miniseries)"},{"name":"Ted Lasso","emoji":"⚽","meta":["comedy, sport","2020–2023","USA"],"description":"An American football coach with no experience of the European game unexpectedly takes charge of an English club and wins over a sceptical squad with unshakeable optimism and kindness. The show made its name with a warm, almost therapeutic tone set against cynical comedy.","fact":"Ted Lasso first appeared years before the series, in NBC promo spots about the English Premier League.","wiki_en":"Ted Lasso"},{"name":"The Bear","emoji":"🐻","meta":["drama, comedy","since 2022","USA"],"description":"A young fine-dining chef returns to his native Chicago to take over the family sandwich shop after his brother's death, and tries to bring order to the chaos of the kitchen and of his own grief. The show is known for its taut, almost documentary kitchen scenes.","fact":"One of its most talked-about episodes is made to look like a single unbroken take, which pushes the kitchen chaos to the limit.","wiki_en":"The Bear (TV series)"},{"name":"Severance","emoji":"🧠","meta":["science fiction, thriller","since 2022","USA"],"description":"Employees of a mysterious corporation undergo a procedure called severance, which literally splits their minds into a work self and an outside self with no memory of each other. A tense dystopia about identity and how far a company can own a life.","fact":"The exteriors and lobby of the corporation were filmed in a real modernist building, the former research laboratories in New Jersey.","wiki_en":"Severance (TV series)"},{"name":"The Boys","emoji":"🦸","meta":["science fiction, black comedy","since 2019","USA"],"description":"In a world where superheroes are the product of a corporation that makes its money from their cult, a group of ordinary people sets out to make the corrupt, brutal \"heroes\" pay for the harm they cause. A merciless parody of the superhero genre and the media-cult industry.","fact":"Many of its characters are recognisable parodies of the best-known comic-book superheroes.","wiki_en":"The Boys (TV series)"},{"name":"House of the Dragon","emoji":"🐲","meta":["fantasy, drama","since 2022","USA"],"description":"This prequel to Game of Thrones is set nearly two hundred years earlier and tells of the bloody civil war for the throne inside House Targaryen known as the Dance of the Dragons. There are far more dragons here than in the parent show, each with a Targaryen rider.","fact":"It is based on George R. R. Martin's book Fire & Blood, written as a mock-historical chronicle of the Targaryen dynasty.","wiki_en":"House of the Dragon"},{"name":"Loki","emoji":"⚡","meta":["science fiction","since 2021","USA"],"description":"After the events of the Avengers films, Loki, god of mischief, lands in the mysterious Time Variance Authority, which polices the integrity of the timeline, and has to work with its agents. It was the first Marvel series to take the multiverse seriously.","fact":"Tom Hiddleston has played Loki since the first Thor in 2011, one of the longest-running roles in the Marvel universe.","wiki_en":"Loki (TV series)"},{"name":"Arcane","emoji":"💜","meta":["animated series, fantasy","2021–2024","USA"],"description":"An animated series set in the world of the game League of Legends, about two sisters from Piltover and Zaun, the wealthy and the destitute halves of one city, whose paths part after a childhood tragedy. Known for its unusual, almost painterly animation.","fact":"It took about six years to make and was one of the most expensive and technically demanding animated productions of its time.","wiki_en":"Arcane (TV series)"},{"name":"Avatar: The Last Airbender","emoji":"🌊","meta":["animated series, fantasy","2005–2008","USA"],"description":"An animated series set in a world split between four peoples, each able to command one of the elements, and about young Avatar Aang, who must master all four and stop the Fire Nation's war. Eastern style with a carefully built, grown-up story.","fact":"The creators consulted martial artists so that each style of bending would be based on a real fighting technique.","wiki_en":"Avatar: The Last Airbender"},{"name":"SpongeBob SquarePants","emoji":"🧽","meta":["animated series, comedy","since 1999","USA"],"description":"An irrepressible yellow sea sponge in square trousers lives in the underwater town of Bikini Bottom, works as a cook at the Krusty Krab and lands in one absurd situation after another with his friends. It became one of the most recognisable cartoon brands in the world.","fact":"Creator Stephen Hillenburg worked as a marine biologist before he went into animation, which clearly shaped the show's underwater setting.","wiki_en":"SpongeBob SquarePants"},{"name":"Naruto","emoji":"🍥","meta":["anime","2002–2007","Japan"],"description":"An anime about young ninja Naruto Uzumaki, who dreams of becoming the strongest leader of his village despite the mighty fox demon sealed inside him. The series follows him growing up, and his friendships and rivalries with his teammates.","fact":"Naruto is also the name of the spiral fish-paste slices served in ramen — and ramen is the hero's favourite food in the show.","wiki_en":"Naruto"},{"name":"One Piece","emoji":"🏴‍☠️","meta":["anime","since 1999","Japan"],"description":"An anime about young pirate Monkey D. Luffy, who eats a devil fruit by chance, gains a rubber body and sets off with his crew in search of the legendary treasure known as the One Piece. One of the longest-running and most profitable anime series ever made.","fact":"The manga it comes from is officially the best-selling comic series by a single author in history.","wiki_en":"One Piece"},{"name":"Attack on Titan","emoji":"🗡️","meta":["anime","2013–2023","Japan"],"description":"Humanity shelters behind giant walls from the man-eating humanoid Titans, until the day the wall is breached by the Colossal Titan. The series slowly uncovers the tangled political and historical roots of the conflict between people and Titans.","fact":"Manga author Hajime Isayama has said the idea came partly from his time working in an internet cafe and dealing with unpredictable customers.","wiki_en":"Attack on Titan"},{"name":"Death Note","emoji":"📓","meta":["anime","2006–2007","Japan"],"description":"High-school student Light Yagami finds a notebook that kills anyone whose name is written in it and decides to purge the world of criminals, becoming the mysterious executioner known as Kira. The brilliant detective L opens an investigation against him.","fact":"The rules for using the Death Note are worked out in such detail that fans have spent years picking over their loopholes and contradictions.","wiki_en":"Death Note"},{"name":"Pokémon","emoji":"⚡","meta":["anime","since 1997","Japan"],"description":"An anime about young trainer Ash Ketchum and his electric Pokémon Pikachu, who travel through different regions catching and training other Pokémon and entering tournaments on the way to becoming champions. Built on the cult video games, it grew into one of the biggest media franchises in the world.","fact":"One 1997 episode gave Japanese viewers seizures with its rapidly flashing frames and has never been broadcast again.","wiki_en":"Pokémon (TV series)"},{"name":"Sailor Moon","emoji":"🌙","meta":["anime","1992–1997","Japan"],"description":"Ordinary Japanese schoolgirl Usagi Tsukino transforms into the sailor-suited warrior Sailor Moon and, together with the other guardian girls, defends the Earth from dark forces. One of the first magical-girl anime to become genuinely popular outside Japan.","fact":"The show played a key part in bringing the magical-girl genre, and anime in general, to Western audiences in the nineties.","wiki_en":"Sailor Moon (TV series)"},{"name":"Mr. Bean","emoji":"🧸","meta":["comedy","1990–1995","United Kingdom"],"description":"A comedy almost without dialogue about Mr Bean, an absurd and eccentric Englishman whose simplest household errands turn without fail into a chain of ridiculous misunderstandings. The physical, visual humour made the show work for viewers in any language.","fact":"With barely any spoken lines, the series travelled the world almost without adaptation or dubbing.","wiki_en":"Mr. Bean"},{"name":"Doctor Who","emoji":"📞","meta":["science fiction","since 1963","United Kingdom"],"description":"A long-running British series about the Doctor, an alien who travels through time and space in a machine shaped like a blue police box and periodically regenerates into a new body. One of the longest-lived science fiction shows on television.","fact":"Regeneration was invented as a plot device in the first place, so that the lead actor could be replaced without stopping the series.","wiki_en":"Doctor Who"},{"name":"Charmed","emoji":"🔮","meta":["fantasy, drama","1998–2006","USA"],"description":"The three Halliwell sisters learn that they descend from a powerful line of witches and have to use their inherited magic to protect the innocent from demons and dark forces. Family drama crossed with a magical battle every week.","fact":"It became one of the longest-running fantasy shows with female leads on American television.","wiki_en":"Charmed"},{"name":"Baywatch","emoji":"🏖️","meta":["drama, action","1989–2001","USA"],"description":"The working days of the lifeguards on the beaches of Malibu, who pull drowning holidaymakers out of the water and also untangle personal dramas and criminal plots. In the nineties it was reckoned one of the most watched television series in the world.","fact":"At its peak, by various estimates, more than a billion viewers around the world watched the show every week.","wiki_en":"Baywatch"},{"name":"ALF","emoji":"👽","meta":["comedy","1986–1990","USA"],"description":"After his alien ship crashes on Earth, a furry creature called ALF moves in with an ordinary American family, hiding from the authorities and causing domestic chaos at every turn. ALF himself is an animatronic puppet, worked by a puppeteer from under the floor.","fact":"Because of the puppet mechanics ALF was rarely shown full-length, and the sets were raised off the floor so the puppeteers could work beneath them.","wiki_en":"ALF (TV series)"},{"name":"Santa Barbara","emoji":"🌴","meta":["soap opera","1984–1993","USA"],"description":"A long-running American soap about the lives, loves and intrigues of several wealthy families in the Californian town of Santa Barbara. Exported widely, it became one of the first foreign series to turn into a mass phenomenon across Eastern Europe in the nineties.","fact":"It ran for almost ten years and counts more than two thousand episodes, roughly one for every working day.","wiki_en":"Santa Barbara (TV series)"},{"name":"The Mentalist","emoji":"🎯","meta":["detective, drama","2008–2015","USA"],"description":"Patrick Jane, a former fake psychic, helps the California Bureau of Investigation solve crimes using not supernatural powers but sharp observation and a grasp of psychology. Alongside that he pursues a private hunt for the serial killer who destroyed his family.","fact":"The lead owes a great deal to real mentalists and cold readers, who create the illusion of reading minds with nothing mystical involved.","wiki_en":"The Mentalist"},{"name":"Suits","emoji":"👔","meta":["drama","2011–2019","USA"],"description":"A gifted young man with no law degree talks his way into a prestigious New York law firm on the strength of an extraordinary memory and quick wits, hiding the deception from colleagues and clients alike. Legal drama wrapped around a story of friendship and mentorship.","fact":"The title plays on two things at once: the sharp suits the lawyers wear and the lawsuits they argue.","wiki_en":"Suits (American TV series)"},{"name":"Lucifer","emoji":"😈","meta":["fantasy, detective","2016–2021","USA"],"description":"The Devil tires of ruling Hell for eternity and moves to Los Angeles, where he opens a nightclub and, on the side, helps the police solve murders thanks to his gift for making people confess what they desire. The series is based on a Vertigo comics character.","fact":"Lucifer first turned up in Neil Gaiman's Sandman comics, long before he got a comic series and a television show of his own.","wiki_en":"Lucifer (TV series)"},{"name":"Supernatural","emoji":"🔥","meta":["fantasy, horror","2005–2020","USA"],"description":"Brothers Sam and Dean Winchester drive across America in an old Chevrolet Impala hunting demons, ghosts and everything else that lurks, and end up at the centre of a war between Heaven and Hell. One of the longest-running horror fantasy shows on American television.","fact":"The black 1967 Chevrolet Impala the brothers drive became as recognisable a symbol of the show as the brothers themselves.","wiki_en":"Supernatural (American TV series)"},{"name":"The Vampire Diaries","emoji":"🧛","meta":["fantasy, drama","2009–2017","USA"],"description":"High-school student Elena Gilbert falls for Stefan Salvatore, a vampire with a conscience, but his unpredictable brother Damon soon turns up in her life and the two are drawn into an eternal rivalry for her heart. It all plays out in the small town of Mystic Falls, thick with supernatural creatures.","fact":"The show was filmed in the real town of Covington, Georgia, which became a popular pilgrimage site for fans.","wiki_en":"The Vampire Diaries"},{"name":"Westworld","emoji":"🤖","meta":["science fiction, drama","2016–2022","USA"],"description":"An enormous theme park is populated by humanlike androids who act out western storylines day after day for wealthy visitors, until signs of genuine consciousness start to show through their programming. The series digs into the nature of consciousness and free will.","fact":"It is based on the 1973 science fiction film of the same name, one of the first Hollywood films to use computer animation.","wiki_en":"Westworld (TV series)"},{"name":"Fargo","emoji":"❄️","meta":["black comedy, crime","since 2014","USA"],"description":"An anthology inspired by the Coen brothers' film, with each season telling its own story of absurd and bloody crime among the snowbound landscapes of the American Midwest. It keeps the trademark Coen mix of black humour and sudden violence.","fact":"Despite the anthology format with new characters every season, a few small plot details link all the seasons together.","wiki_en":"Fargo (TV series)"},{"name":"Mr. Robot","emoji":"💻","meta":["drama, thriller","2015–2019","USA"],"description":"A gifted but mentally fragile programmer and hacker spends his nights with an underground anarchist group that plans to wipe out the debt records of the largest corporation in the world. The show is known for its accurate portrayal of real hacking and its unconventional camerawork.","fact":"Creator Sam Esmail has been into programming since his teens and kept cybersecurity consultants on set to make the hacking scenes ring true.","wiki_en":"Mr. Robot"},{"name":"Brooklyn Nine-Nine","emoji":"👮","meta":["sitcom","2013–2021","USA"],"description":"A comedy about the working days of the eccentric detectives of the 99th precinct in Brooklyn, led by the strict but fair Captain Raymond Holt. Police investigations run alongside an endless stream of pranks and needling between partners.","fact":"Captain Holt was one of the first openly gay Black characters to lead an American comedy series.","wiki_en":"Brooklyn Nine-Nine"},{"name":"Seinfeld","emoji":"🥨","meta":["sitcom","1989–1998","USA"],"description":"A sitcom about New York comedian Jerry Seinfeld and three oddball friends, with episodes built around utterly everyday trifles and absurd petty disputes. It was jokingly called \"the show about nothing\" because it had almost no running storylines.","fact":"The 1998 finale drew tens of millions of Americans and became one of the most widely watched send-offs in television history.","wiki_en":"Seinfeld"},{"name":"Brigada","emoji":"🔫","meta":["drama, crime","2002","Russia"],"description":"Four childhood friends in the Moscow of the nineties turn, step by step, from ordinary young men into the leaders of a major criminal gang. The series traces the rise and the inevitable fall of the crew against a turbulent decade.","fact":"Sergey Bezrukov, who played gang boss Sasha Bely, was identified with the role by audiences for years afterwards.","wiki_en":"Brigada"},{"name":"Seventeen Moments of Spring","emoji":"🕵️","meta":["drama, spy","1973","USSR"],"description":"Soviet intelligence officer Maxim Isaev, working inside Nazi Germany under the name of Standartenführer Stierlitz, tries to head off separate peace talks between the Germans and the Western allies in the last months of the war. One of the most cult Soviet television series.","fact":"Its lines and scenes sank so deeply into the culture that they spawned an entire genre of jokes about Stierlitz.","wiki_en":"Seventeen Moments of Spring"},{"name":"The Meeting Place Cannot Be Changed","emoji":"🚔","meta":["detective, drama","1979","USSR"],"description":"Adapted from the Vayner brothers' novel about the Moscow criminal investigation department in the first post-war years, where the experienced detective Gleb Zheglov and the young Vladimir Sharapov clash over how crime should be fought. Widely held to be one of the best Soviet crime dramas.","fact":"Zheglov, played by Vladimir Vysotsky, was one of the last major roles of the actor's life.","wiki_en":"The Meeting Place Cannot Be Changed"},{"name":"Liquidation","emoji":"🕶️","meta":["detective, drama","2007","Russia, Ukraine"],"description":"A crime series set in post-war Odessa in 1946, where the criminal investigation department tries to get a grip on rampant banditry led by a shadowy crime boss known as the Academic. The show recreates the colour and the speech of post-war Odessa.","fact":"The Odessa dialect and the characters' turns of phrase were being quoted far beyond the city almost at once.","wiki_en":"Liquidation (TV series)","wiki_ru":"Ликвидация (телесериал)"},{"name":"Streets of Broken Lights","emoji":"🌃","meta":["detective","since 1997","Russia"],"description":"One of the first and longest-running Russian crime series, following the working days of detectives in the St Petersburg criminal investigation department as they solve a fresh case each episode. It set off a whole wave of similar homegrown police franchises.","fact":"It is based on the books of Andrey Kivinov, who served in the St Petersburg criminal investigation department himself.","wiki_en":"Streets of Broken Lights"},{"name":"Interny","emoji":"🩺","meta":["sitcom","2010–2016","Russia"],"description":"A comedy about the working days of young medical interns at a Moscow hospital under the caustic and exacting Doctor Bykov. The format borrows heavily from the popular American medical sitcoms, reworked for Russian realities.","fact":"Doctor Bykov was played by Ivan Okhlobystin, until then better known as an arthouse actor and a screenwriter.","wiki_en":"Interny (TV series)","wiki_ru":"Интерны"},{"name":"Kitchen","emoji":"🍳","meta":["sitcom","2012–2016","Russia"],"description":"A sitcom about the cooks and staff of an expensive restaurant, where a talented but green young chef tries to make his way under a short-tempered and demanding head chef. It spawned several feature-length sequels and spin-offs.","fact":"The hot-tempered head chef Viktor Barinov was played by Dmitry Nazarov, and it is the role the show is remembered for.","wiki_en":"Kitchen (Russian TV series)","wiki_ru":"Кухня (телесериал)"},{"name":"Univer","emoji":"🎓","meta":["sitcom","2007–2011","Russia"],"description":"A youth sitcom about students sharing a hall of residence at a Moscow university, shot multi-camera with an audience laughing off screen. It became one of the most visible young-audience projects on Russian television in the 2000s.","fact":"It got a sequel, Univer: The New Dorm, which carried on in the same halls of residence with a fresh set of characters.","wiki_en":"Univer (TV series)","wiki_ru":"Универ (телесериал)"},{"name":"Fizruk","emoji":"🏋️","meta":["sitcom","2014–2018","Russia"],"description":"A former crime boss known as Foma comes out of prison and takes a job as a physical education teacher at an ordinary school, bringing his gangster habits and his own brand of humour into a settled school routine. Dmitry Nagiev plays the lead.","fact":"Foma does not go into teaching out of any calling: he needs to get close to the daughter of his old boss.","wiki_en":"Fizruk"},{"name":"Svaty","emoji":"🍷","meta":["comedy","2008–2019","Ukraine, Russia"],"description":"A comedy about two families of very different means and outlooks whose children have married, leaving the parents obliged to deal with each other and put up with each other's temperaments. Most of it plays out at one family's village house.","fact":"It was shot in Ukraine, and its cast brought together well-known actors from several post-Soviet countries at once.","wiki_en":"Svaty (TV series)","wiki_ru":"Сваты"},{"name":"Daddy's Daughters","emoji":"👧","meta":["sitcom","2007–2013","Russia"],"description":"A sitcom about a psychologist whose wife has walked out, leaving him to raise five daughters of wildly different temperaments on his own and barely keep up with their antics. Shot multi-camera with an audience laughing off screen.","fact":"Years after the finale the show got a sequel, in which the grown-up daughters returned with a new generation of children.","wiki_en":"Daddy's Daughters"},{"name":"My Fair Nanny","emoji":"🧹","meta":["sitcom","2004–2009","Russia"],"description":"A sitcom about a guileless but irresistible girl from the provinces who unexpectedly becomes the nanny in the household of a wealthy Moscow producer and gradually wins over his whole family. It is the Russian adaptation of the American sitcom The Nanny.","fact":"The heroine arrives in Moscow from Mariupol, and her broad accent with its unmistakable intonations became the show's trademark.","wiki_en":"My Fair Nanny","wiki_ru":"Моя прекрасная няня"},{"name":"Not Born Beautiful","emoji":"👓","meta":["melodrama","2005–2006","Russia"],"description":"A melodrama about a modest young woman, plain by the standards of the glossy magazines, who takes a job at a fashion house and, in the face of her colleagues' mockery, gradually wins both success and love. It is the Russian version of a popular Latin American format about an ugly duckling conquering the fashion world.","fact":"The original format, a Colombian telenovela, has been adapted by broadcasters in dozens of countries, and the Russian version was one of the most successful.","wiki_en":"Not Born Beautiful","wiki_ru":"Не родись красивой"},{"name":"The Boy's Word: Blood on the Asphalt","emoji":"🥊","meta":["drama, crime","2023","Russia"],"description":"A drama about the teenage street gangs of Kazan in the late eighties, where boys from neighbouring courtyards live by the harsh unwritten law of the street. On release it set off a wide public argument about juvenile crime.","fact":"After the premiere several Russian regions held special discussions and prevention measures, fearing that teenagers would copy the characters.","wiki_en":"The Boy's Word: Blood on the Asphalt"},{"name":"To the Lake","emoji":"❄️","meta":["drama, thriller","2019–2022","Russia"],"description":"After a lethal virus breaks out in Russia, a group of chance travelling companions tries to drive across an emptied, unravelling country to a safe refuge at a remote lake. It is based on Yana Vagner's novel Vongozero.","fact":"It premiered in Russia shortly before the COVID-19 pandemic began; the original Russian title means simply \"Epidemic\".","wiki_en":"To the Lake"},{"name":"Mazhor","emoji":"🚓","meta":["drama, crime","2014–2019","Russia"],"description":"After one serious misstep, the spoiled son of a high-ranking official is packed off by his father to serve as a rank-and-file detective in the Moscow police, where he has to earn his colleagues' respect from nothing. Crime plots wrapped around a pampered young man growing up.","fact":"After the television seasons the character's story was carried on in a feature film released in cinemas.","wiki_en":"Mazhor","wiki_ru":"Мажор (телесериал)"},{"name":"The Method","emoji":"🔦","meta":["detective, thriller","2015–2018","Russia"],"description":"An eccentric investigator with unorthodox, almost frightening methods takes a young policewoman on as his partner to hunt maniacs and serial killers together. The series is known for its bleak atmosphere and unconventional camerawork.","fact":"The lead is played by Konstantin Khabensky, and the show was compared in style with foreign thrillers about serial killers.","wiki_en":"The Method (TV series)"},{"name":"A Cop from Rublyovka","emoji":"🚨","meta":["comedy","2016–2019","Russia"],"description":"A simple-minded beat officer is transferred to an exclusive settlement for the super-rich on Rublyovka, where he has to deal with the whims and oddities of very wealthy residents while staying an honest, artless man at heart. Police plots crossed with a comedy of manners.","fact":"It got a feature-length sequel, A Cop from Rublyovka: New Year's Mayhem, which became a hit in Russian cinemas.","wiki_en":"A Cop from Rublyovka","wiki_ru":"Полицейский с Рублёвки"},{"name":"Well, Just You Wait!","emoji":"🐺","meta":["cartoon","since 1969","USSR"],"description":"A Soviet cartoon about a shambolic but stubborn Wolf who spends dozens of short episodes failing to catch a cheerful and resourceful Hare. With almost no dialogue, it runs on expressive mime and musical numbers.","fact":"The Wolf's line \"Well, Hare, just you wait!\", repeated in nearly every episode, stuck so firmly that it gave the whole series its name.","wiki_en":"Well, Just You Wait!"},{"name":"Smeshariki","emoji":"🐰","meta":["animated series","since 2004","Russia"],"description":"A Russian cartoon about round, funny little ball-shaped creatures who live in an invented forest world and introduce young viewers to friendship, science and helping each other through simple everyday stories. It has been exported and adapted for broadcast in many countries.","fact":"Abroad it has gone out under other names, including the GoGoRiki and KikoRiki versions made for different international markets.","wiki_en":"Smeshariki"},{"name":"Masha and the Bear","emoji":"🐻","meta":["animated series","since 2009","Russia"],"description":"A cartoon about Masha, an unstoppable little girl whose endless mischief constantly tests the patience of the kind bear who has taken her in and is worn out by her energy. One of the most successful Russian animation projects, popular far beyond the country.","fact":"The episode \"Masha plus Porridge\" has drawn billions of views on YouTube and is among the most watched videos in the site's history.","wiki_en":"Masha and the Bear"},{"name":"Homeland","emoji":"🎯","meta":["political thriller","2011–2020","USA"],"description":"CIA officer Carrie Mathison, who lives with bipolar disorder, suspects a marine just returned from captivity of working with terrorists. Based on the Israeli series Hatufim, it holds the viewer through political intrigue and Claire Danes's performance.","fact":"The show is based on the Israeli series Hatufim, created by Gideon Raff.","wiki_en":"Homeland (TV series)"},{"name":"Lie to Me","emoji":"👁️","meta":["crime drama","2009–2011","USA"],"description":"Psychologist Cal Lightman and his colleagues solve crimes by reading people's micro-expressions and body language. Each episode combines a case with almost documentary asides on the nature of lying and of emotion.","fact":"The lead character is modelled on the real psychologist Paul Ekman, who advised the show's makers.","wiki_en":"Lie to Me","wiki_ru":"Обмани меня (телесериал, 2009)"},{"name":"Criminal Minds","emoji":"🧠","meta":["crime drama","2005–2020","USA"],"description":"Agents of the FBI's behavioural analysis unit build psychological profiles of serial offenders in order to predict their next move. The series made profiling one of the most recognisable subjects on crime television.","fact":"The Behavioral Analysis Unit of the series is modelled on a real FBI department at Quantico.","wiki_en":"Criminal Minds","wiki_ru":"Мыслить как преступник"},{"name":"Gotham","emoji":"🦇","meta":["crime drama","2014–2019","USA"],"description":"Set in Gotham City years before Bruce Wayne becomes Batman, when young detective James Gordon is only starting to take on the city's crime. Along the way the viewer watches the future villains of the DC comics turn into the characters everyone recognises.","fact":"The makers promised to show the making of almost every classic Batman adversary before Batman himself ever appears.","wiki_en":"Gotham (TV series)","wiki_ru":"Готэм (телесериал)"},{"name":"The Flash","emoji":"⚡","meta":["superhero","2014–2023","USA"],"description":"Forensic scientist Barry Allen gains super speed after a lightning strike and becomes the superhero who guards Central City. The show is part of the so-called Arrowverse, The CW's shared universe with Arrow and Supergirl.","fact":"Barry Allen is played by Grant Gustin, who first appeared in the role in episodes of Arrow.","wiki_en":"The Flash (2014 TV series)","wiki_ru":"Флэш (фильм)"},{"name":"Arrow","emoji":"🏹","meta":["superhero","2012–2020","USA"],"description":"Billionaire Oliver Queen comes back after five years on a deserted island and starts fighting crime in Star City behind the mask of an archer vigilante. The series launched a whole network of connected superhero shows on The CW.","fact":"It was Arrow that opened the so-called Arrowverse, the shared universe of several CW superhero series.","wiki_en":"Arrow (TV series)"},{"name":"Supergirl","emoji":"🦸‍♀️","meta":["superhero","2015–2021","USA"],"description":"Kara Danvers, Superman's cousin, hides her powers for years before deciding to defend National City in the open. The show mixes superhero action with themes of finding yourself and believing in yourself.","fact":"Kara Danvers was born on Krypton before Superman, but she was delayed on the way and reached Earth after he did.","wiki_en":"Supergirl (TV series)"},{"name":"Altered Carbon","emoji":"🧬","meta":["cyberpunk","2018–2020","USA"],"description":"In the distant future human consciousness can be moved between bodies known as sleeves, and Takeshi Kovacs, a former rebel soldier, investigates the murder of one of the richest people on the planet. Adapted from Richard Morgan's novel, it is famous for its bleak cyberpunk look.","fact":"The hero's sleeve is played by different actors in different seasons — that is part of how the story works.","wiki_en":"Altered Carbon (TV series)"},{"name":"The Umbrella Academy","emoji":"☂️","meta":["superhero","2019–2024","USA"],"description":"Seven adopted children with unusual powers, raised by an eccentric billionaire, are forced back together to stop the end of the world. The series is adapted from the comics by Gerard Way, frontman of My Chemical Romance.","fact":"One of the siblings, Number Five, was stuck in the future for decades and came back in the body of a teenager.","wiki_en":"The Umbrella Academy (TV series)"},{"name":"You","emoji":"📚","meta":["psychological thriller","2018–2025","USA"],"description":"Charming bookshop employee Joe Goldberg falls obsessively in love with women and will manipulate anyone to get close to whoever he wants. Adapted from Caroline Kepnes's novel, it is built on the hero's inner monologue in voice-over.","fact":"It first aired on Lifetime and only became a hit after Netflix bought the rights.","wiki_en":"You (TV series)","wiki_ru":"Ты (телесериал)"},{"name":"Sex Education","emoji":"🎓","meta":["teen drama","2019–2023","United Kingdom"],"description":"Otis, a shy schoolboy whose mother works as a sex therapist, finds himself running an unofficial clinic on relationships and sexuality at his school. The series mixes blunt humour with a warm coming-of-age story.","fact":"It was filmed in Wales, although the story is set in an invented English town.","wiki_en":"Sex Education (TV series)"},{"name":"Killing Eve","emoji":"🔪","meta":["crime thriller","2018–2022","United Kingdom"],"description":"Bored security service officer Eve Polastri is assigned to track down Villanelle, an elusive and eccentric contract killer, and a dangerous mutual attraction grows between the two women. Adapted from Luke Jennings's novellas.","fact":"Every season had a woman showrunner of its own: the first was written by Phoebe Waller-Bridge, the rest by other writers.","wiki_en":"Killing Eve"},{"name":"True Blood","emoji":"🩸","meta":["horror drama","2008–2014","USA"],"description":"Once synthetic blood is invented, vampires step out of the shadows and try to fit into life in a small Louisiana town, where waitress Sookie Stackhouse has an unusual gift of her own. Adapted from Charlaine Harris's novels.","fact":"The title plays on the contrast between true blood and the synthetic substitute the vampires drink instead.","wiki_en":"True Blood","wiki_ru":"Настоящая кровь"},{"name":"Oz","emoji":"🔒","meta":["prison drama","1997–2003","USA"],"description":"Life in Emerald City, an experimental maximum-security unit, is shown with nothing prettified: violence, gangs and the fight to stay alive. It was one of HBO's first original dramas and opened the channel's road to grown-up television.","fact":"It is regarded as the forerunner of HBO shows like The Sopranos and The Wire.","wiki_en":"Oz (TV series)"},{"name":"24","emoji":"⏱️","meta":["spy thriller","2001–2010","USA"],"description":"Each season covers a single day in the life of counter-terrorism agent Jack Bauer, in real time, episode by episode, hour by hour. The real-time format with its ticking countdown became the show's signature.","fact":"The on-screen clock keeps running even through the commercial breaks — part of the show's trademark style.","wiki_en":"24 (TV series)"},{"name":"CSI: Crime Scene Investigation","emoji":"🔬","meta":["crime drama","2000–2015","USA"],"description":"A team of Las Vegas forensic scientists solves crimes with fingerprints, blood analysis and ballistics. The series took forensics mainstream and spawned several spin-offs around the world.","fact":"Its popularity produced the so-called CSI effect: jurors coming to court with inflated expectations of real forensic science.","wiki_en":"CSI: Crime Scene Investigation"},{"name":"CSI: Miami","emoji":"🕶️","meta":["crime drama","2002–2012","USA"],"description":"A spin-off about the forensics team of sunny Miami, led by Lieutenant Horatio Caine and his showy one-liners just before the title sequence. It kept the original's format and added a brighter, more cinematic look.","fact":"Horatio Caine's \"Yeah\" and his signature pause before the cut became an internet meme.","wiki_en":"CSI: Miami"},{"name":"Law & Order","emoji":"⚖️","meta":["crime drama","1990–2010","USA"],"description":"Every episode splits in two: first the police investigate the crime, then the prosecutors take the case to court. The case-per-episode format and that unmistakable scene-change sting made it one of the longest-running shows in American television history.","fact":"The Law & Order franchise produced several spin-offs and was revived in 2022 after a long break.","wiki_en":"Law & Order","wiki_ru":"Закон и порядок"},{"name":"Law & Order: Special Victims Unit","emoji":"🛡️","meta":["crime drama","since 1999","USA"],"description":"This Law & Order spin-off follows the New York police unit that investigates sexually motivated crime, led by detective Olivia Benson. It is one of the longest-running prime-time series in the United States.","fact":"Mariska Hargitay has played Olivia Benson since the very first season in 1999, longer than any other character in the franchise.","wiki_en":"Law & Order: Special Victims Unit","wiki_ru":"Закон и порядок: Специальный корпус"},{"name":"Bones","emoji":"🦴","meta":["crime drama","2005–2017","USA"],"description":"Forensic anthropologist Temperance Brennan works with FBI agent Seeley Booth to solve crimes from the skeletal remains of the victims. The series draws on the work of the writer and anthropologist Kathy Reichs, who advised the production.","fact":"Inside the show Brennan writes crime novels herself, and her fictional heroine is called Kathy Reichs, after the real woman.","wiki_en":"Bones (TV series)"},{"name":"Castle","emoji":"🖋️","meta":["detective","2009–2016","USA"],"description":"Richard Castle, a bestselling crime novelist, wins permission to shadow New York detective Kate Beckett on her cases and find material for new books. The show runs on the easy chemistry between the two leads and on sharp dialogue.","fact":"The novels the character Castle \"writes\" were actually published as real bestsellers under his name.","wiki_en":"Castle (TV series)"},{"name":"NCIS","emoji":"⚓","meta":["crime drama","since 2003","USA"],"description":"A special unit of the naval criminal investigative service works cases involving US Navy sailors and marines. It grew out of a spin-off from JAG and became one of the longest-running dramas on American television.","fact":"NCIS stands for Naval Criminal Investigative Service, a genuine agency under the US Navy.","wiki_en":"NCIS (TV series)","wiki_ru":"Морская полиция: Спецотдел"},{"name":"ER","emoji":"🏥","meta":["medical drama","1994–2009","USA"],"description":"Life in the emergency department of a Chicago hospital, told at the headlong, almost documentary pace of shifts and of lives saved or lost. Created by Michael Crichton, it set the standard for medical drama for decades to come.","fact":"One of its first regular cast members was George Clooney, who played the paediatrician Doug Ross.","wiki_en":"ER (TV series)"},{"name":"The West Wing","emoji":"🏛️","meta":["political drama","1999–2006","USA"],"description":"The working days of an invented US presidential administration, from the speechwriters to the national security adviser, seen through the eyes of the White House staff. Creator Aaron Sorkin made his name with long dialogue delivered on the move.","fact":"The trick of shooting a long conversation while the characters walk became known to fans as the walk and talk, and it is the show's signature.","wiki_en":"The West Wing","wiki_ru":"Западное крыло (телесериал)"},{"name":"American Horror Story","emoji":"👻","meta":["horror anthology","since 2011","USA"],"description":"Every season tells a self-contained horror story, from a haunted house to a psychiatric hospital, while the cast carries over from season to season in new parts. The anthology format let creators Ryan Murphy and Brad Falchuk play with different styles.","fact":"Many of the actors, Jessica Lange and Sarah Paulson among them, played entirely different characters in different seasons.","wiki_en":"American Horror Story"},{"name":"Grimm","emoji":"📖","meta":["fantasy detective","2011–2017","USA"],"description":"Portland police detective Nick Burkhardt learns that he descends from a line of hunters of the creatures in the Brothers Grimm fairy tales, and has to combine ordinary police work with a secret hunt for monsters. A case-per-episode procedural set against the mythology of a hidden world.","fact":"The title points straight at the Brothers Grimm, whose tales are reworked here as accounts of real creatures.","wiki_en":"Grimm (TV series)","wiki_ru":"Гримм"},{"name":"Smallville","emoji":"🌽","meta":["superhero","2001–2011","USA"],"description":"Clark Kent grows up in the small town of Smallville long before he becomes Superman, dealing with first love, school trouble and the slow realisation of what he can do. For years the show stuck to an unspoken rule: no tights and no flying.","fact":"The makers avoided showing the hero in the classic Superman suit for a very long time; it happened only in the closing episode.","wiki_en":"Smallville","wiki_ru":"Тайны Смолвиля"},{"name":"Star Trek: The Original Series","emoji":"🖖","meta":["science fiction","1966–1969","USA"],"description":"The crew of the starship Enterprise, under Captain Kirk, explores deep space, meeting new civilisations and holding to a principle of non-interference. Gene Roddenberry's series laid the foundations of one of the largest science fiction franchises ever built.","fact":"Spock's Vulcan greeting \"live long and prosper\" was devised by actor Leonard Nimoy, who based it on the Jewish priestly blessing.","wiki_en":"Star Trek: The Original Series","wiki_ru":"Звёздный путь"},{"name":"Battlestar Galactica","emoji":"🌌","meta":["science fiction","2004–2009","USA"],"description":"After human civilisation is wiped out by the Cylon robots, a small fleet of survivors led by the warship Galactica searches space for the legendary planet Earth. This bleak reboot of the 1978 series won praise for the depth of its political and religious themes.","fact":"Some of the Cylons are physically indistinguishable from humans, which keeps the story permanently on edge.","wiki_en":"Battlestar Galactica (2004 TV series)"},{"name":"Hannibal","emoji":"🍽️","meta":["psychological thriller","2013–2015","USA"],"description":"Young FBI profiler Will Graham grows close to the brilliant psychiatrist Hannibal Lecter without suspecting his dark secret. Based on Thomas Harris's characters, it stands out for an elaborate, almost painterly visual style.","fact":"For all its cult standing, the show was shut down after three seasons because the ratings were modest.","wiki_en":"Hannibal (TV series)","wiki_ru":"Ганнибал"},{"name":"Riverdale","emoji":"🍒","meta":["teen drama","2017–2023","USA"],"description":"The characters of the classic Archie Andrews comics turn up in a much darker Riverdale, where secrets and crimes lie behind a cosy facade. It starts as a murder mystery and drifts further and further into genre experiment.","fact":"It is based on Archie Comics, which began as light-hearted teenage stories with no noir about them at all.","wiki_en":"Riverdale (2017 TV series)"},{"name":"Teen Wolf","emoji":"🐺","meta":["teen horror","2011–2017","USA"],"description":"Ordinary schoolboy Scott McCall becomes a werewolf after a mysterious beast attacks him, and has to learn to live with his new nature without losing himself or his friends. Inspired by the 1985 film of the same name, it builds an entirely separate story.","fact":"Despite a title that points back to the 1985 comedy with Michael J. Fox, the series is far darker in tone than the original.","wiki_en":"Teen Wolf (TV series)","wiki_ru":"Волчонок (телесериал)"},{"name":"13 Reasons Why","emoji":"🎧","meta":["drama","2017–2020","USA"],"description":"After a classmate's tragic death, schoolboy Clay Jensen receives a set of audio cassettes on which she explains what led her to that decision. Adapted from Jay Asher's novel, it set off a broad public argument about how television talks about adolescent trauma.","fact":"After the first season the makers revised some scenes for later releases, on the advice of psychologists.","wiki_en":"13 Reasons Why","wiki_ru":"13 причин почему"},{"name":"Misfits","emoji":"🌩️","meta":["science fiction comedy","2009–2013","United Kingdom"],"description":"A group of young people serving community sentences gain unusual powers after a strange thunderstorm, and have to learn to live with them while remaining the same bunch of delinquents. The show is known for its black humour and deliberately anti-heroic tone.","fact":"Robert Sheehan, who played one of the key parts, left the production after the second season.","wiki_en":"Misfits (TV series)"},{"name":"Skins","emoji":"🎉","meta":["teen drama","2007–2013","United Kingdom"],"description":"The series shows the lives of a group of British teenagers — parties, first love, addictions and family trouble — with nothing censored and no moralising. Every two seasons the cast of characters is replaced completely and grows up alongside a new generation of actors.","fact":"Almost the whole cast of each generation was recruited from untrained young actors at open auditions.","wiki_en":"Skins (British TV series)"},{"name":"Will & Grace","emoji":"🏙️","meta":["sitcom","1998–2006","USA"],"description":"Will, a gay lawyer, shares a New York apartment with his best friend Grace, while their eccentric friends Jack and Karen sharpen the comedy. It was one of the first shows on mainstream American television to make a gay man the sitcom's leading good guy.","fact":"After eight seasons the show was revived in 2017 and ran for three further seasons.","wiki_en":"Will & Grace","wiki_ru":"Уилл и Грейс"},{"name":"Young Sheldon","emoji":"🧪","meta":["sitcom","2017–2024","USA"],"description":"This prequel to The Big Bang Theory covers the childhood of the prodigy Sheldon Cooper in a small Texas town, where his formidable intellect does not always meet with understanding at home or at school. It is a single-camera sitcom with a narrator.","fact":"The narrator is Jim Parsons, the same actor who played the adult Sheldon in the original show.","wiki_en":"Young Sheldon"},{"name":"Parks and Recreation","emoji":"🌳","meta":["mockumentary sitcom","2009–2015","USA"],"description":"Leslie Knope, an indefatigable official in the parks department of the small town of Pawnee, tries with almost naive enthusiasm to improve life for its citizens, running into bureaucracy and the indifference of her colleagues. A mockumentary from the producers of The Office.","fact":"It was originally conceived as a direct spin-off of The Office, but grew into a project of its own.","wiki_en":"Parks and Recreation","wiki_ru":"Парки и зоны отдыха"},{"name":"30 Rock","emoji":"📺","meta":["sitcom","2006–2013","USA"],"description":"Liz Lemon, writer and showrunner of a fictional sketch show, balances temperamental stars, an eccentric boss and the chaos inside the NBC network. Tina Fey built the series on her own years working on Saturday Night Live.","fact":"The eccentric network executive was played by Alec Baldwin, who won several Emmys for the part.","wiki_en":"30 Rock","wiki_ru":"Студия 30"},{"name":"Everybody Hates Chris","emoji":"🎒","meta":["sitcom","2005–2009","USA"],"description":"A semi-autobiographical account of the childhood and teenage years of comedian Chris Rock in a poor part of Brooklyn in the 1980s. The adult Chris, voiced by Rock himself, comments on it all in voice-over with an ironic distance.","fact":"In the story Chris is bussed to a school on the other side of the city, where he turns out to be the only Black pupil.","wiki_en":"Everybody Hates Chris"},{"name":"Married... with Children","emoji":"🛋️","meta":["sitcom","1987–1997","USA"],"description":"Hapless shoe salesman Al Bundy, his idle family and the show's relentlessly ironic tone became the antidote to the saccharine family sitcoms of the eighties. It was one of the first shows to put a frankly dysfunctional yet loving family on screen.","fact":"It was one of the first shows on the young Fox network and one of the biggest hits of its early schedule.","wiki_en":"Married... with Children"},{"name":"King of the Hill","emoji":"🍖","meta":["animated sitcom","1997–2010","USA"],"description":"Conservative Texan Hank Hill sells propane and propane accessories, raises an unusual son and tries to hold on to a familiar way of life in a changing world. Mike Judge's series is known for calm, almost realistic humour set against absurdist cartoon comedy.","fact":"Mike Judge voices several characters himself, both Hank Hill and Boomhauer, the neighbour whose muttering nobody can make out.","wiki_en":"King of the Hill","wiki_ru":"Царь горы"},{"name":"American Dad!","emoji":"🦅","meta":["animated sitcom","since 2005","USA"],"description":"CIA agent Stan Smith tries to keep up an outwardly perfect family while fighting terrorists and aliens, and his household pet, a talking alien named Roger, causes chaos at every turn. Seth MacFarlane created it as a more surreal counterpart to Family Guy.","fact":"Roger the alien can take on an endless number of guises and professions for the sake of whatever scheme is running.","wiki_en":"American Dad!"},{"name":"Beavis and Butt-Head","emoji":"🤘","meta":["animated comedy","1993–1997","USA"],"description":"Two witless metalhead teenagers comment on music videos and stumble into ridiculous situations, a caricature of adolescent idleness and ignorance. Mike Judge's series became one of the emblems of nineties MTV.","fact":"After several cases of viewers copying the pair's dangerous stunts, the show faced criticism and censorship in the United States.","wiki_en":"Beavis and Butt-Head","wiki_ru":"Бивис и Баттхед"},{"name":"Daria","emoji":"📓","meta":["animated comedy","1997–2002","USA"],"description":"Daria Morgendorffer, a sardonic schoolgirl who is indifferent to every school convention, watches the stupidity around her from an ironic distance. This spin-off of Beavis and Butt-Head came out far more talkative and observant than its parent show.","fact":"Daria first appeared in Beavis and Butt-Head as a supporting character, before she was given a show of her own.","wiki_en":"Daria (TV series)"},{"name":"Adventure Time","emoji":"🍦","meta":["animated fantasy","2010–2018","USA"],"description":"A boy called Finn and his best friend Jake, a magical dog with a stretchable body, travel through the post-apocalyptic Land of Ooo, full of strange creatures and kingdoms. Under the childlike animation the show hides unexpectedly deep themes of growing up and of loss.","fact":"The Land of Ooo turns out to be the Earth of the distant future, after an unnamed global catastrophe.","wiki_en":"Adventure Time"},{"name":"Gravity Falls","emoji":"🌲","meta":["animated mystery","2012–2016","USA"],"description":"Twins Dipper and Mabel spend the summer with their eccentric great-uncle in the town of Gravity Falls, full of enigmatic creatures and secrets. Alex Hirsch built the series as one big puzzle, with coded messages in every episode's credits.","fact":"Creator Alex Hirsch voices both Grunkle Stan and the main villain, Bill Cipher.","wiki_en":"Gravity Falls"},{"name":"Barboskins","emoji":"🐶","meta":["animated series","Russia"],"description":"A large family of dog-like creatures, the Barboskins, works through everyday domestic questions, and each episode teaches the viewer a simple moral lesson. It is one of the most popular Russian cartoon series of the past decade.","fact":"Each of the Barboskin children has one firmly fixed trait, from resourcefulness to being a crushing bore.","wiki_en":"Barboskins","wiki_ru":"Барбоскины"},{"name":"Fixiki","emoji":"🔧","meta":["animated series","since 2010","Russia"],"description":"The Fixies are tiny little people who live inside household appliances and repair them from within, explaining to children along the way how familiar things actually work. Educational material mixed with warm humour and a theme tune everyone knows.","fact":"The idea grew out of Eduard Uspensky's children's book about the little people who come with the warranty.","wiki_en":"Fixiki","wiki_ru":"Фиксики"},{"name":"Three Cats","emoji":"🐱","meta":["animated series","since 2015","Russia"],"description":"Three young kittens, Korzhik, Karamelka and Kompot, explore the world around them and land in funny, instructive situations alongside their cat parents. One of the most recognisable Russian cartoon brands for preschoolers.","fact":"The three kittens' names all come from home cooking and sweets: a biscuit, a caramel and a fruit drink.","wiki_en":"Three Cats","wiki_ru":"Три кота"},{"name":"Luntik","emoji":"🌙","meta":["animated series","2006–2019","Russia"],"description":"A strange creature born from a drop of moon milk falls to Earth, gets to know the natural world and learns about friendship, kindness and helping others alongside his insect neighbours. It became one of the most recognisable and longest-running Russian cartoons for preschoolers.","fact":"His name comes from the Russian word for the Moon: that is where he was born before he fell to Earth.","wiki_en":"Luntik and His Friends","wiki_ru":"Лунтик и его друзья"},{"name":"Teenage Mutant Ninja Turtles","emoji":"🐢","meta":["animated action","1987–1996","USA"],"description":"Four mutated ninja turtles — Leonardo, Donatello, Raphael and Michelangelo — fight New York crime from beneath the streets alongside their rat sensei. The original 1987 cartoon turned an independent comic into one of the great pop-culture phenomena of the era.","fact":"Each of the four turtles wears a mask of its own colour and is named after a Renaissance artist.","wiki_en":"Teenage Mutant Ninja Turtles (1987 TV series)"},{"name":"DuckTales","emoji":"🦆","meta":["animated adventure","1987–1990","USA"],"description":"Miserly billionaire duck Scrooge McDuck sets off on dangerous treasure-hunting expeditions around the world with his three great-nephews. A classic Disney cartoon that did much to define the look of adventure animation in the late eighties.","fact":"Scrooge McDuck first appeared in Carl Barks's comics in 1947, long before the series existed.","wiki_en":"DuckTales (1987 TV series)"},{"name":"Chip 'n Dale: Rescue Rangers","emoji":"🐿️","meta":["animated adventure","1989–1990","USA"],"description":"Detective chipmunks Chip and Dale and their team — the inventor mouse Gadget, the strongman Monterey Jack and the fly Zipper — take on cases too small for the big investigators. It became one of Disney's most popular productions of the late eighties.","fact":"The name of the heroes' detective agency plays on the gap between minuscule sleuths and very large problems.","wiki_en":"Chip 'n Dale: Rescue Rangers","wiki_ru":"Чип и Дейл спешат на помощь"},{"name":"Darkwing Duck","emoji":"🦆","meta":["animated superhero series","1991–1992","USA"],"description":"A mysterious duck superhero known as Darkwing Duck defends the city of St Canard from a gang of ridiculous but dangerous villains, and raises an adopted daughter on the side. It parodies classic superheroes like Batman while keeping Disney's house humour.","fact":"The hero's catchphrase — \"I am the terror that flaps in the night\" — turned into a meme long ago.","wiki_en":"Darkwing Duck"},{"name":"Tom and Jerry","emoji":"🐭","meta":["animated comedy","1940–1958","USA"],"description":"Tom the cat tries endlessly and hopelessly to catch the cunning mouse Jerry across a run of short, silent or near-silent gag cartoons. One of the most recognisable and longest-lived double acts in the history of cinema, and an Oscar winner several times over.","fact":"Several shorts in the series won the Academy Award for best animated short film.","wiki_en":"Tom and Jerry","wiki_ru":"Том и Джерри"},{"name":"Looney Tunes","emoji":"🐰","meta":["animated comedy","1930–1969","USA"],"description":"Warner Bros.'s anthology of short cartoons gave the world Bugs Bunny, Daffy Duck, Porky Pig and dozens of other characters with their trademark comic routines. The series did much to define the language of American cartoon comedy in the twentieth century.","fact":"Bugs Bunny's \"What's up, doc?\" is among the most recognisable lines in the history of American animation.","wiki_en":"Looney Tunes"},{"name":"The Flintstones","emoji":"🦕","meta":["animated sitcom","1960–1966","USA"],"description":"The Flintstone family lives in the Stone Age, but their daily life parodies the typical American suburban existence of the mid-twentieth century, complete with foot-powered cars and appliances made of dinosaurs. It was the first cartoon series to air in American prime time.","fact":"Fred Flintstone's battle cry \"Yabba-dabba-doo!\" became one of the best-known lines in the history of animation.","wiki_en":"The Flintstones"},{"name":"The Jetsons","emoji":"🚀","meta":["animated sitcom","1962–1963","USA"],"description":"The Jetson family lives in a futuristic city of the future with flying cars, robot helpers and moving pavements. Hanna-Barbera conceived it as the mirror image of The Flintstones: instead of the Stone Age, the world of the distant future.","fact":"Despite only one original season, The Jetsons remains one of the most recognisable images of the future in twentieth-century pop culture.","wiki_en":"The Jetsons"},{"name":"Scooby-Doo, Where Are You!","emoji":"🐕","meta":["animated detective","1969–1970","USA"],"description":"Cowardly dog Scooby-Doo and his four teenage friends drive around in a van called the Mystery Machine unmasking supposed ghosts and monsters, who almost always turn out to be very ordinary crooks. The case-per-episode format and the villain's line about those meddling kids became genre classics.","fact":"In nearly every episode of the original series the mysterious monster turned out to be an ordinary person in a costume.","wiki_en":"Scooby-Doo, Where Are You!"},{"name":"Winx Club","emoji":"🧚‍♀️","meta":["animated fantasy","2004–2019","Italy"],"description":"Six fairy girls learn to handle magic at Alfea, a school of sorcery, and defend the Magic Dimension from dark forces. The Italian cartoon became one of the most recognisable European animation projects aimed at girls.","fact":"Creator Iginio Straffi drew on the Japanese magical-girl genre, with its stories about girls who can work magic.","wiki_en":"Winx Club"},{"name":"Samurai Jack","emoji":"⏳","meta":["animated action","2001–2017","USA"],"description":"A Japanese samurai, flung by the evil demon Aku into a distant dystopian future, searches for a way back to his own time to stop the evil at its source. Genndy Tartakovsky's series stands out for its minimalist look and almost wordless storytelling.","fact":"After a long gap the show finally got a fifth, concluding season in 2017, more than ten years after the fourth.","wiki_en":"Samurai Jack","wiki_ru":"Самурай Джек"},{"name":"Dragon Ball Z","emoji":"🐉","meta":["shonen anime","1989–1996","Japan"],"description":"Saiyan warrior Son Goku and his friends defend Earth from ever more powerful opponents while collecting the magical Dragon Balls, which grant any wish. It became one of the most influential anime franchises and set the fashion for long fights and heroes who keep levelling up.","fact":"It is the direct continuation of the earlier anime Dragon Ball, based on Akira Toriyama's manga.","wiki_en":"Dragon Ball Z"},{"name":"Fullmetal Alchemist: Brotherhood","emoji":"⚗️","meta":["shonen anime","2009–2010","Japan"],"description":"Brothers Edward and Alphonse Elric, who lost parts of their bodies trying to resurrect their mother with forbidden alchemy, search for the philosopher's stone that could restore what they lost. Brotherhood follows Hiromu Arakawa's manga more closely than the earlier 2003 adaptation.","fact":"The first adaptation in 2003 diverged from the manga's plot, so years later the studio made a second, more faithful series.","wiki_en":"Fullmetal Alchemist: Brotherhood","wiki_ru":"Стальной алхимик"},{"name":"Neon Genesis Evangelion","emoji":"🤖","meta":["mecha anime","1995–1996","Japan"],"description":"Teenagers are recruited to pilot giant biomechanical Evangelions against the mysterious beings known as Angels that threaten humanity. Under the shell of a mecha action series sits a dense psychological drama about trauma, loneliness and the fear of closeness.","fact":"The original ending was so unconventional and abstract that the studio later released an alternative version as feature films.","wiki_en":"Neon Genesis Evangelion"},{"name":"Inuyasha","emoji":"🏹","meta":["shonen anime","2000–2004","Japan"],"description":"Schoolgirl Kagome falls through a well into the Sengoku era and joins forces with the half-demon Inuyasha to gather the shards of the shattered magical Jewel of Four Souls. Based on Rumiko Takahashi's manga, it mixes adventure with romance.","fact":"Rumiko Takahashi is also known as the creator of other cult manga series, Ranma ½ among them.","wiki_en":"Inuyasha"},{"name":"Cowboy Bebop","emoji":"🎷","meta":["neo-noir anime","1998–1999","Japan"],"description":"A crew of bounty hunters aboard the battered spaceship Bebop travels the Solar System looking for work, while each character's past is gradually revealed through separate, almost self-contained episodes. Famous for its jazz soundtrack and cinematic direction.","fact":"The music was written by composer Yoko Kanno, and the jazz of the soundtrack is inseparable from the show's cult standing.","wiki_en":"Cowboy Bebop"},{"name":"Hunter × Hunter","emoji":"🎣","meta":["shonen anime","2011–2014","Japan"],"description":"A boy called Gon Freecss sits the examination to become a Hunter in order to find his missing father, making friends along the way and running into opponents whose powers obey an intricate internal logic. The 2011 series is the more faithful and complete adaptation of Yoshihiro Togashi's manga.","fact":"The source manga has been published with long interruptions for several decades now, because of the author's health.","wiki_en":"Hunter × Hunter (2011 TV series)"},{"name":"Jujutsu Kaisen","emoji":"🌀","meta":["shonen anime","since 2020","Japan"],"description":"High-school student Yuji Itadori swallows the cursed finger of a legendary demon and is pulled into a hidden war between sorcerer exorcists and the curses born of human negative emotion. Based on Gege Akutami's manga, it quickly became one of the most visible anime of its time.","fact":"The manga has a prequel: a short run of chapters that Gege Akutami drew before the main story.","wiki_en":"Jujutsu Kaisen"},{"name":"Demon Slayer: Kimetsu no Yaiba","emoji":"🗡️","meta":["shonen anime","since 2019","Japan"],"description":"After a demon wipes out his entire family, Tanjiro Kamado becomes a demon slayer in order to find a way of making his sister Nezuko human again. Based on Koyoharu Gotouge's manga, it is famous for ufotable's spectacular animation and became a box-office phenomenon in Japan.","fact":"The feature films spun off from the series are among the highest-grossing releases in Japanese cinema history.","wiki_en":"Demon Slayer: Kimetsu no Yaiba"},{"name":"My Hero Academia","emoji":"💥","meta":["shonen anime","since 2016","Japan"],"description":"In a world where almost everyone has a superpower, a boy with none at all dreams of becoming a hero, and gets his chance when a legendary superhero passes his own strength on to him. Based on Kohei Horikoshi's manga, it is one of the most successful superhero anime there is.","fact":"Kohei Horikoshi has said that American superhero comics were what inspired him to create the series.","wiki_en":"My Hero Academia"},{"name":"Tokyo Ghoul","emoji":"👹","meta":["seinen anime","2014–2018","Japan"],"description":"After a botched organ transplant, ordinary student Ken Kaneki turns into a half-ghoul, forced to balance between the world of humans and the world of creatures who feed on human flesh. Based on Sui Ishida's manga, it works through identity and alienation via a bleak urban mythology.","fact":"Because the later seasons parted company with the original manga, they divided the fans of the source material.","wiki_en":"Tokyo Ghoul"},{"name":"Berserk","emoji":"⚔️","meta":["seinen anime","1997–1998","Japan"],"description":"Guts, a lone mercenary who has survived on the strength of an enormous sword and his own fury, is drawn into a dark story of betrayal and revenge in a grim pseudo-medieval world. The original 1997 series, from Kentaro Miura's manga, remains one of the most revered dark fantasy adaptations.","fact":"Kentaro Miura's source manga ran for more than thirty years and was left unfinished when he died in 2021.","wiki_en":"Berserk (1997 TV series)"},{"name":"Ranma ½","emoji":"💧","meta":["comedy anime","1989–1992","Japan"],"description":"After falling into a cursed spring, young martial artist Ranma Saotome turns into a girl on contact with cold water and back again with hot. This comedy from Rumiko Takahashi's manga runs on endless confusion around the hero's double identity.","fact":"The hero's curse is only one of many in the show: almost every significant character has a transformation of their own.","wiki_en":"Ranma ½"},{"name":"Haikyu!!","emoji":"🏐","meta":["sports anime","2014–2020","Japan"],"description":"Shoyo Hinata, a short but stubborn schoolboy, dreams of becoming a great volleyball player in spite of his height, and joins the Karasuno school team alongside Tobio Kageyama, at once his rival and his partner. Based on Haruichi Furudate's manga, it is known for its kinetic matches and its motivating tone.","fact":"The show is credited with a noticeable surge of interest in volleyball and school volleyball clubs among Japanese pupils.","wiki_en":"Haikyu!!"},{"name":"Ghost in the Shell: Stand Alone Complex","emoji":"🌐","meta":["cyberpunk anime","2002–2005","Japan"],"description":"In a future where consciousness can be plugged straight into the network, Major Motoko Kusanagi and Section 9 investigate cybercrimes that verge on philosophy: where does the human end and the machine begin. The series deepens the themes of the 1995 film in episodic form.","fact":"The subtitle Stand Alone Complex points to the show's central idea: copycats reproducing a crime that never had an original.","wiki_en":"Ghost in the Shell: Stand Alone Complex"},{"name":"Guest from the Future","emoji":"🛸","meta":["science fiction","1985","USSR"],"description":"Schoolboy Kolya Gerasimov stumbles into the Moscow of the future and comes back with Alisa Selezneva, a girl whom space pirates from the future are hunting. This five-part film from Kir Bulychev's novella became one of the best-loved Soviet science fiction projects for children.","fact":"Alisa was played by schoolgirl Natalya Guseva, who became an instant idol for Soviet teenagers and received sacks of fan mail.","wiki_en":"Guest from the Future","wiki_ru":"Гостья из будущего"},{"name":"The Adventures of Sherlock Holmes and Doctor Watson","emoji":"🎩","meta":["detective","1979–1986","USSR"],"description":"This Soviet cycle of films about the detective of Baker Street and his loyal doctor friend is held to be one of the most faithful and respected adaptations of Arthur Conan Doyle. Vasily Livanov and Vitaly Solomin created Holmes and Watson as several generations of viewers came to picture them.","fact":"Vasily Livanov was made an honorary MBE for his Sherlock Holmes — a rare recognition for a foreign actor.","wiki_en":"The Adventures of Sherlock Holmes and Doctor Watson","wiki_ru":"Приключения Шерлока Холмса и доктора Ватсона"},{"name":"Shadows Disappear at Noon","emoji":"🌾","meta":["drama","1971","USSR"],"description":"A serial that follows several generations of a Siberian village through the Soviet era, from the Civil War to the post-war years. Adapted from Anatoly Ivanov's novel, it was one of the first genuinely large-scale Soviet television series.","fact":"It is based on a novel by Anatoly Ivanov, who also wrote the book behind the later series The Eternal Call.","wiki_en":"Shadows Disappear at Noon","wiki_ru":"Тени исчезают в полдень"},{"name":"The Eternal Call","emoji":"🔔","meta":["drama","1973–1983","USSR"],"description":"A serialised saga that follows a large Siberian family across half a century of Russian history, from the start of the century to the Second World War. Adapted from Anatoly Ivanov's epic novel, it was one of the most ambitious Soviet television series of its day.","fact":"Filming stretched over a good ten years, and the story spans several historical eras of twentieth-century Russia.","wiki_en":"The Eternal Call","wiki_ru":"Вечный зов"},{"name":"Sledstviye vedut ZnaToKi","emoji":"🕵️","meta":["detective","1971–1989","USSR"],"description":"A cycle of television films about three investigators — Znamensky, Tomin and Kibrit, whose initials spell out the Russian word for \"the experts\" — solving cases for the Soviet police. One of the longest-running and best-loved crime series on Soviet television, on air for almost two decades.","fact":"The cycle's song about a service that is \"dangerous and hard\" long ago became the unofficial anthem of the police.","wiki_en":"Sledstviye vedut ZnaToKi","wiki_ru":"Следствие ведут знатоки"},{"name":"Gangster Petersburg","emoji":"🏙️","meta":["crime drama","2000–2007","Russia"],"description":"A serialised project based on Andrey Konstantinov's novels, showing how the criminal gangs of St Petersburg formed and went to war in the nineties, through the eyes of gangsters, journalists and investigators. It became a landmark of Russian gangster television in the early 2000s.","fact":"It consists of several separate serials, joined by a shared world and by characters who partly overlap.","wiki_en":"Gangster Petersburg","wiki_ru":"Бандитский Петербург (телесериал)"},{"name":"La Piovra","emoji":"🐙","meta":["crime drama","1984–2001","Italy"],"description":"Police commissioner Corrado Cattani wages an uncompromising war on the Sicilian mafia, whose tentacles reach, like an octopus, right up to the top of the state. The Italian series became a cult hit far beyond Italy, not least in the Soviet Union of the late eighties.","fact":"The Italian title means \"the octopus\", precisely because of that metaphor of the mafia as a many-tentacled monster.","wiki_en":"La Piovra"},{"name":"O Clone","emoji":"👯","meta":["TV series","2001–2002","Brazil"],"description":"This telenovela braids the forbidden love of a Moroccan girl, Jade, and a Brazilian, Lucas, together with a science fiction strand about the secret cloning of a human being. The mix of eastern colour, melodrama and scientific intrigue made it an enormous hit well beyond Brazil.","fact":"The title comes from the storyline about creating a genetic copy of one of the characters, a rare subject for a telenovela of the early 2000s.","wiki_en":"O Clone"},{"name":"Escrava Isaura","emoji":"⛓️","meta":["TV series","1976","Brazil"],"description":"Set on a Brazilian coffee plantation in the nineteenth century, where the beautiful slave Isaura becomes the target of her cruel owner's pursuit despite her secretly noble birth. Adapted from Bernardo Guimarães's novel, it was one of the first Brazilian telenovelas to win over audiences abroad.","fact":"Its broadcast in the Soviet Union in the late eighties was a cultural event and one of the first mass encounters with the telenovela there.","wiki_en":"Escrava Isaura","wiki_ru":"Рабыня Изаура (телесериал)"},{"name":"Los Ricos También Lloran","emoji":"💔","meta":["TV series","1979","Mexico"],"description":"Mariana, a poor orphan, ends up in the house of a wealthy Mexican family, falls in love with its heir and goes through a string of melodramatic trials for the sake of her happiness. The Mexican telenovela was one of the first foreign series shown on Russian television in the early nineties, and it caused a genuine frenzy.","fact":"Its Russian premiere in 1991 drew an enormous audience and became one of the first mass television obsessions of the post-Soviet years.","wiki_en":"Los Ricos También Lloran"},{"name":"Simplemente María","emoji":"🧵","meta":["TV series","1989","Mexico"],"description":"Maria, a modest seamstress, travels from poverty to success and love, running into scheming and betrayal along the way. The Mexican telenovela became one of the cult foreign series for Russian audiences in the early nineties, alongside Los Ricos También Lloran.","fact":"For a while the heroine's name was used in post-Soviet popular culture as shorthand for the whole Latin American telenovela genre.","wiki_en":"Simplemente María (1989 telenovela)"},{"name":"Sesame Street","emoji":"🟡","meta":["children's programme","since 1969","USA"],"description":"An educational programme in which Muppet puppets teach young viewers letters, numbers and simple lessons about life on an invented city street. One of the longest-running and most influential children's television projects in the world, it has spawned dozens of national adaptations.","fact":"The Muppets were created by puppeteer Jim Henson, who later became famous for The Muppet Show as well.","wiki_en":"Sesame Street"},{"name":"Yeralash","emoji":"🎬","meta":["short film magazine","since 1974","USSR / Russia"],"description":"Each instalment of this film magazine collects several short comic sketches from school and childhood, often with a twist in the last line. One of the longest-running projects on the Russian screen, and a place where dozens of future well-known actors appeared as children.","fact":"Hundreds of children have passed through the cast over the decades, and many of them went on to become well-known adult actors.","wiki_en":"Yeralash","wiki_ru":"Ералаш (киножурнал)"},{"name":"Kadetstvo","emoji":"🎖️","meta":["youth drama","2006–2008","Russia"],"description":"The series follows the daily lives of teenagers at a military cadet school: their friendships, their first loves and their attempts to live up to strict military discipline. One of the notable Russian youth series of the mid-2000s, made for the STS channel.","fact":"Consultants from real cadet schools worked on the production, to get the atmosphere of the institution right.","wiki_en":"Kadetstvo","wiki_ru":"Кадетство"},{"name":"Realnye Patsany","emoji":"🎥","meta":["mockumentary comedy","since 2010","Russia"],"description":"Shot as a fake documentary about the everyday life of Kolyan, an ordinary lad from Perm, and his friends, with their particular brand of humour, their accidental adventures and an almost documentary tone. One of the most successful long-running productions on the TNT channel.","fact":"It is set in Perm, and many scenes were shot right out on the streets and in the courtyards of the real city.","wiki_en":"Realnye Patsany","wiki_ru":"Реальные пацаны"},{"name":"Molodyozhka","emoji":"🏒","meta":["sports drama","Russia"],"description":"A series about a junior ice hockey team in a provincial town, where sporting ambition is tangled up with the private dramas of the players and their coaches. One of the few Russian series built around hockey, and a notable hit for the STS channel.","fact":"The hockey scenes were shot with consultants and doubles drawn from real players.","wiki_en":"Molodyozhka","wiki_ru":"Молодёжка"},{"name":"Olga","emoji":"🍷","meta":["tragicomedy","2016–2021","Russia"],"description":"Olga, a sharp-tongued and far from exemplary mother, tries to make sense of her troubled family's life, in a mix of black humour and unexpectedly warm moments. The TNT series stands out from the usual sitcoms for its bolder, more honest tone.","fact":"The blunt, quick-witted Olga is played by actress Yana Troyanova.","wiki_en":"Olga (TV series)","wiki_ru":"Ольга (телесериал)"},{"name":"Tayny sledstviya","emoji":"🔍","meta":["detective","since 2000","Russia"],"description":"Across dozens of seasons, prosecutor's investigator Maria Shvetsova works the most varied crimes in St Petersburg, and has become one of the most recognisable figures on Russian crime television. The show has been on air for more than two decades, which makes it one of the longest-running projects on Russian TV.","fact":"Maria Shvetsova has been played from the very first season, and in every sequel, by actress Anna Kovalchuk.","wiki_en":"Tayny sledstviya","wiki_ru":"Тайны следствия"},{"name":"Soderzhanki","emoji":"💎","meta":["drama","since 2019","Russia"],"description":"The series follows several Moscow women who are in relationships with wealthy patrons, and gradually exposes the underside of an outwardly comfortable world of big money. A notable production for the streaming platform Start, it made its name through frankness and pointed social subject matter.","fact":"It was one of the first major original productions by a Russian streaming platform to go beyond broadcast television.","wiki_en":"Soderzhanki","wiki_ru":"Содержанки"},{"name":"Dom-2","emoji":"💒","meta":["reality show","since 2004","Russia"],"description":"The participants live in a closed compound trying to build relationships and eventually win a house of their own, while viewers watch their daily life and their quarrels almost around the clock. One of the longest-running reality shows in the world, and a real phenomenon of Russian popular culture in the 2000s.","fact":"Its hosts over the years have included Ksenia Sobchak and Ksenia Borodina, who herself started out as a contestant.","wiki_en":"Dom-2","wiki_ru":"Дом-2"},{"name":"Poslednyi Geroy","emoji":"🏝️","meta":["reality show","since 2001","Russia"],"description":"Contestants live on a desert island, compete in challenges and vote each other out one by one until a single winner is left. The Russian version of the international Survivor format, it was one of the first big reality productions on Russian television.","fact":"The first seasons of the Russian version were hosted by the actor Sergey Bodrov Jr.","wiki_en":"Poslednyi Geroy","wiki_ru":"Последний герой (телепередача)"},{"name":"The Adventures of Captain Vrungel","emoji":"⛵","meta":["animated series","1976–1979","USSR"],"description":"The hapless but likeable Captain Vrungel and his crew set off to sail round the world on a yacht with a very telling name, blundering into ridiculous and dangerous adventures on the way. This Soviet cartoon, from Andrey Nekrasov's novella, became a classic of Russian animation.","fact":"The captain's famous line — whatever you name the yacht is how she will sail — became a set phrase in Russian.","wiki_en":"The Adventures of Captain Vrungel","wiki_ru":"Приключения капитана Врунгеля"},{"name":"iCarly","emoji":"💻","meta":["sitcom","2007–2012","USA"],"description":"Schoolgirl Carly Shay and her friends run their own internet show straight out of her bedroom, while living through the usual teenage adventures and misunderstandings. The Nickelodeon series was one of the first on mainstream TV to make amateur video blogging its central subject.","fact":"Almost ten years after the original ended, the show got a sequel with the characters all grown up.","wiki_en":"iCarly"},{"name":"Hannah Montana","emoji":"🎤","meta":["sitcom","2006–2011","USA"],"description":"Ordinary schoolgirl Miley Stewart leads a double life, hiding from her classmates the fact that she is really the pop star Hannah Montana. The series made a star of the young Miley Cyrus and became one of Disney Channel's flagship shows of the late 2000s.","fact":"The lead was played by Miley Cyrus, daughter of the country singer Billy Ray Cyrus, who also appeared in the show.","wiki_en":"Hannah Montana"},{"name":"Wizards of Waverly Place","emoji":"✨","meta":["sitcom","2007–2012","USA"],"description":"Three wizard children in an ordinary New York family learn magic in secret, knowing that only one of them will get to keep their powers into adulthood. The Disney Channel series mixes teen sitcom with fantasy and family rivalry.","fact":"The lead was played by Selena Gomez, for whom the show was one of her first big successes as an actress.","wiki_en":"Wizards of Waverly Place"},{"name":"Zoey 101","emoji":"🏫","meta":["sitcom","2005–2008","USA"],"description":"Zoey Brooks enrols at a prestigious boarding school that has only just gone co-educational, and works through the usual teenage twists of campus life with her friends. The Nickelodeon series was one of Jamie Lynn Spears's first major acting jobs.","fact":"The lead was played by Jamie Lynn Spears, younger sister of the singer Britney Spears.","wiki_en":"Zoey 101"},{"name":"Drake & Josh","emoji":"🎸","meta":["sitcom","2004–2007","USA"],"description":"Two very different stepbrothers — the cocksure musician Drake and the luckless nerd Josh — have to share a room and land in comic scrapes at every turn. The Nickelodeon series became one of the most recognisable teen sitcoms of the mid-2000s.","fact":"Drake Bell, who played Drake, also wrote and performed the show's theme song.","wiki_en":"Drake & Josh"},{"name":"Hey Arnold!","emoji":"🏈","meta":["animated series","1996–2004","USA"],"description":"Arnold, a good-natured boy with an oddly shaped head, lives with his grandparents in a big-city apartment building and goes through the business of growing up with his friends, against a thoroughly recognisable urban backdrop. The Nickelodeon series stands out for its realistic, warm view of city kids.","fact":"The shape of the hero's head was a running joke inside the show for years and never got a single settled explanation.","wiki_en":"Hey Arnold!","wiki_ru":"Эй, Арнольд!"},{"name":"Rugrats","emoji":"👶","meta":["animated series","1991–2004","USA"],"description":"The world seen through the eyes of a group of babies, who treat ordinary household situations as genuine adventures full of imagination and small dangers. One of Nickelodeon's most successful cartoons of the nineties, and the channel's calling card.","fact":"The viewer understands the babies perfectly while the adults hear only babble — half the show's jokes rest on that.","wiki_en":"Rugrats"},{"name":"The Wild Thornberrys","emoji":"🦁","meta":["animated series","1998–2004","USA"],"description":"Eliza Thornberry, daughter of travelling documentary makers, gains the magical ability to talk to animals and uses it to help wildlife during her family's expeditions around the world. The Nickelodeon series mixes adventure with educational material about the environment.","fact":"The show explains her gift as the work of a mysterious nature spirit she met in Africa.","wiki_en":"The Wild Thornberrys"},{"name":"Phineas and Ferb","emoji":"🛠️","meta":["animated series","2007–2015","USA"],"description":"Two irrepressible stepbrothers dream up and build an impossible invention every single day of the summer, while their older sister tries in vain to expose them to their parents. The Disney Channel series is built on a repeating episode structure and became one of the channel's best-loved cartoons.","fact":"Nearly every episode includes the question of where Perry has gone: the boys' pet, who is in fact a secret agent.","wiki_en":"Phineas and Ferb"},{"name":"Miraculous: Tales of Ladybug & Cat Noir","emoji":"🐞","meta":["animated superhero series","since 2015","France"],"description":"Parisian schoolchildren Marinette and Adrien secretly turn into the superheroes Ladybug and Cat Noir to face a villain hunting their magical artefacts, with neither of them realising who the other really is behind the mask. The French cartoon became a wide international success.","fact":"Creator Thomas Astruc has said he was inspired by classic superhero comics and Japanese magical-girl anime at the same time.","wiki_en":"Miraculous: Tales of Ladybug & Cat Noir"},{"name":"Naruto: Shippuden","emoji":"🍥","meta":["shonen anime","2007–2017","Japan"],"description":"The continuation of the story of the ninja Naruto Uzumaki follows him growing up and working towards becoming the strongest and most respected ninja in his village, in spite of the dangerous spirit sealed inside him since birth. A direct sequel to the original Naruto and one of the best-known shonen titles anywhere.","fact":"Naruto and Shippuden together run to more than seven hundred episodes.","wiki_en":"Naruto: Shippuden"},{"name":"Bleach","emoji":"💀","meta":["shonen anime","2004–2012","Japan"],"description":"Ordinary schoolboy Ichigo Kurosaki gains the powers of a shinigami, a guide of souls, and takes on the duty of protecting the living and the dead from evil spirits. Based on Tite Kubo's manga, it is known for its vivid battles and memorable character designs.","fact":"After a long break the series got a continuation in 2022, adapting the final arc of the manga.","wiki_en":"Bleach (TV series)","wiki_ru":"Блич"},{"name":"One-Punch Man","emoji":"👊","meta":["parody anime","since 2015","Japan"],"description":"Saitama is so strong that he beats any opponent with a single punch, which turns his main problem from fighting evil into ordinary boredom. Based on ONE's webcomic, it parodies the clichés of the superhero genre while remaining spectacular action.","fact":"One-Punch Man started life as an amateur webcomic by an author under the pen name ONE, and went viral before it was ever published professionally.","wiki_en":"One-Punch Man"},{"name":"The Expanse","emoji":"🛰️","meta":["science fiction","2015–2022","USA"],"description":"In a future where humanity has spread across the Solar System, political tension between Earth, Mars and the asteroid belt tips into full conflict after a mysterious discovery. Based on James S. A. Corey's novels, it is famous for its carefully worked-out scientific plausibility.","fact":"The show was cancelled by SyFy after the third season, then continued when Amazon bought the rights.","wiki_en":"The Expanse (TV series)","wiki_ru":"Пространство"},{"name":"Dark","emoji":"🌑","meta":["science fiction drama","2017–2020","Germany"],"description":"Children go missing in a small German town, and the search uncovers a secret that binds several generations of local families together through loops in time. The German Netflix series is known for its intricate, carefully built structure and its bleak atmosphere.","fact":"It was the first original German-language series Netflix ever produced.","wiki_en":"Dark (TV series)","wiki_ru":"Тьма (телесериал)"},{"name":"See","emoji":"🌫️","meta":["science fiction","2019–2022","USA"],"description":"In the distant future a virus has left almost all of humanity blind, and the birth of children who can see becomes a source of fear and religious awe. Starring Jason Momoa, the series examines how a society works when it has adapted completely to life without sight.","fact":"To portray blindness more truthfully, the makers worked with specialists and with blind consultants.","wiki_en":"See (TV series)"},{"name":"The Good Wife","emoji":"👩‍⚖️","meta":["legal drama","2009–2016","USA"],"description":"After a public scandal involving her politician husband, Alicia Florrick returns to practising law to support her family and rebuild her own life and career. The series combines a case-per-episode format with a long-running political and personal drama.","fact":"The plot draws heavily on real political scandals involving the infidelities of public figures.","wiki_en":"The Good Wife","wiki_ru":"Хорошая жена"},{"name":"How to Get Away with Murder","emoji":"🖤","meta":["legal thriller","2014–2020","USA"],"description":"Annalise Keating, a charismatic and ruthless law professor, pulls a group of her students into a tangle of real court cases and her own dark secrets. The series is known for a non-linear structure that shuffles the present and the future within a single season.","fact":"The lead was played by Viola Davis, the first Black actress to win the Emmy for a leading dramatic role.","wiki_en":"How to Get Away with Murder"},{"name":"Billions","emoji":"💰","meta":["drama","2016–2023","USA"],"description":"Ambitious prosecutor Chuck Rhoades enters a drawn-out war with powerful hedge fund manager Bobby Axelrod, turning the pursuit of financial crime into a personal vendetta. The series shows Wall Street from inside, through power, money and uncompromising ambition.","fact":"Chuck Rhoades is played by Paul Giamatti and the billionaire Bobby Axelrod by Damian Lewis.","wiki_en":"Billions (TV series)"},{"name":"State Border","emoji":"🪖","meta":["war drama","1980–1988","USSR"],"description":"A cycle of serialised films about the defenders of the Soviet state border in different historical periods, from the revolution to the post-war years. One of the most ambitious Soviet television projects about the border guards, made as several separate films within one cycle.","fact":"Every film in the cycle was made by the Belarusian studio Belarusfilm.","wiki_en":"State Border","wiki_ru":"Государственная граница (телесериал)"},{"name":"Kamenskaya","emoji":"🔎","meta":["detective","1999–2011","Russia"],"description":"Anastasia Kamenskaya, a clever and outwardly unremarkable officer of the criminal investigation department, solves difficult crimes with her intellect and analytical mind rather than with force. Based on Alexandra Marinina's crime novels, it became a landmark of Russian detective television around the turn of the century.","fact":"Alexandra Marinina, who wrote the source novels, served in the police herself for many years.","wiki_en":"Kamenskaya","wiki_ru":"Каменская (телесериал)"},{"name":"Uboynaya Sila","emoji":"🔫","meta":["crime drama","2000–2005","Russia"],"description":"The series follows the working days of the St Petersburg homicide squad as they investigate the gravest crimes of the nineties and the 2000s. One of the landmark Russian crime series of the early 2000s, continuing the line of the homegrown police procedural.","fact":"It was shot in St Petersburg and drew heavily on how the criminal investigation department actually worked at the time.","wiki_en":"Uboynaya Sila","wiki_ru":"Убойная сила"},{"name":"Voroniny","emoji":"🏠","meta":["sitcom","2009–2019","Russia"],"description":"The large, noisy Voronin family, three generations of it, shares one flat and spends its time falling out and making up over domestic trifles. The Russian adaptation of the American sitcom Everybody Loves Raymond became one of the longest-running productions on the STS channel.","fact":"Kostya Voronin is played throughout by Georgy Dronov, and his wife Vera by Ekaterina Volkova.","wiki_en":"Voroniny","wiki_ru":"Воронины"},{"name":"Schastlivy Vmeste","emoji":"👞","meta":["sitcom","2006–2013","Russia"],"description":"Shoe salesman Gena Bukin dreams of a better life but is stuck with a loud family that does not always understand him, in a small provincial town. The Russian adaptation of the American sitcom Married... with Children became one of the biggest hits of TNT's early schedule.","fact":"It is the official Russian adaptation of the American sitcom Married... with Children.","wiki_en":"Schastlivy Vmeste","wiki_ru":"Счастливы вместе"},{"name":"6 Kadrov","emoji":"🎭","meta":["sketch show","2006–2014","Russia"],"description":"Each edition collects several short comic sketches played by a regular company of actors, who take recognisable everyday situations and push them to absurdity. One of the most prominent sketch shows on Russian television in the 2000s, made for the STS channel.","fact":"The title points to the idea that a complete joke can be told in no more than a few frames.","wiki_en":"6 Kadrov","wiki_ru":"6 кадров"},{"name":"Nasha Russia","emoji":"🎪","meta":["sketch show","2006–2009","Russia"],"description":"A sketch show that parades a gallery of grotesque characters from every corner of Russia, from migrant labourers to security guards, mocking social types and stereotypes everyone recognises. It became one of the most prominent entertainment shows on the TNT channel in the late 2000s.","fact":"The format owes a great deal to the British sketch show Little Britain, reworked for Russian realities.","wiki_en":"Nasha Russia","wiki_ru":"Наша Russia"},{"name":"Dayosh Molodyozh!","emoji":"🎊","meta":["sketch show","2006–2010","Russia"],"description":"A sketch show in which a regular company of young actors plays out short comic vignettes about student and youth life. One of the notable entertainment shows on the STS channel in the late 2000s.","fact":"Several performers who passed through the cast went on to become significant figures in Russian comedy television.","wiki_en":"Dayosh Molodyozh!","wiki_ru":"Даёшь молодёжь!"},{"name":"Zhuki","emoji":"🪲","meta":["comedy","2019–2023","Russia"],"description":"Three friends from a provincial town unexpectedly inherit a bankrupt factory and try to turn it into a working business, despite having no experience whatsoever. The series mixes light comedy with a warm story about friendship and growing up.","fact":"The first season came out on a YouTube channel before the show settled on the PREMIER platform.","wiki_en":"Zhuki (TV series)","wiki_ru":"Жуки (телесериал)"},{"name":"Trigger","emoji":"💢","meta":["drama","2018–2020","Russia"],"description":"Psychotherapist Artyom Streletsky uses provocative, unorthodox methods, knocking his patients off balance for the sake of their own recovery. Made for Channel One, the series brings psychology and trauma to a wide national television audience.","fact":"The hero's methods are based on a real school of psychotherapy — provocative therapy, which works through unorthodox tactics.","wiki_en":"Trigger (TV series)","wiki_ru":"Триггер (телесериал)"},{"name":"Twin Peaks: The Return","emoji":"🦉","meta":["mystery drama","2017","USA"],"description":"A quarter of a century after the original, David Lynch returns to the town of Twin Peaks with a new season that is stranger and more experimental still. The third season of the cult series is made as a single film many hours long.","fact":"All eighteen episodes were directed by David Lynch himself, a real rarity for a television project on this scale.","wiki_en":"Twin Peaks: The Return"},{"name":"Everybody Loves Raymond","emoji":"🍝","meta":["sitcom","1996–2005","USA"],"description":"Sports journalist Raymond Barone tries to keep the peace at home while living literally across the road from parents who interfere in every detail of his life. One of the most successful American sitcoms of the turn of the century, and the winner of a great many Emmys.","fact":"The show is the basis of several international adaptations, among them the Russian series Voroniny.","wiki_en":"Everybody Loves Raymond"},{"name":"Roseanne","emoji":"👩‍👧‍👦","meta":["sitcom","1988–1997","USA"],"description":"The series shows the life of the Conners, a working-class family in provincial Illinois, without the idealisation sitcoms usually apply, money troubles and domestic rows included. Roseanne Barr's show was one of the first on American television to talk honestly about life on a low wage.","fact":"More than twenty years after the finale, the show was revived in 2018 with its original principal cast.","wiki_en":"Roseanne","wiki_ru":"Розанна"},{"name":"The Cosby Show","emoji":"👨‍👩‍👧‍👦","meta":["sitcom","1984–1992","USA"],"description":"A comfortable middle-class Black family — obstetrician Cliff Huxtable, his lawyer wife and their five children — made this one of the highest-rated American sitcoms of the eighties. The show did much to change how Black families were portrayed in American popular culture.","fact":"At its height the series was the highest-rated show on American television for several seasons running.","wiki_en":"The Cosby Show"},{"name":"Dallas","emoji":"🤠","meta":["drama","1978–1991","USA"],"description":"The scheming and the family wars of the wealthy Ewing oil dynasty of Texas, complete with affairs, betrayals and a struggle for control of a business empire. One of the most successful prime-time series of the eighties, it set off a whole fashion for soaps about rich families.","fact":"The twist of bringing a character back from the dead, explained by a whole season turning out to be a dream, is among the most argued-over devices in television history.","wiki_en":"Dallas (1978 TV series)"},{"name":"Dynasty","emoji":"👑","meta":["drama","1981–1989","USA"],"description":"The wealthy Carrington oil magnates of Denver, whose internal feuds and luxurious way of life became the template for the eighties prime-time melodrama. The show is remembered for its spectacular outfits and for one of the most recognisable feuds between two women on television.","fact":"Its costumes did much to set the fashion for enormous shoulders and the opulent wardrobe now associated with the eighties.","wiki_en":"Dynasty (1981 TV series)"},{"name":"Beverly Hills, 90210","emoji":"🌴","meta":["teen drama","1990–2000","USA"],"description":"The series follows a group of pupils at a privileged school in a wealthy part of Los Angeles through their romances, friendships and growing up among all that money. One of the first genuinely successful youth dramas, it set the fashion for the genre for decades.","fact":"The title comes from the real postal code of the Beverly Hills district: 90210.","wiki_en":"Beverly Hills, 90210"},{"name":"Melrose Place","emoji":"🏢","meta":["drama","1992–1999","USA"],"description":"This spin-off of Beverly Hills, 90210 follows a group of young adults renting flats in the same Los Angeles apartment complex, through romances, betrayals and professional ambition. It became one of the leading prime-time melodramas of the nineties.","fact":"It was originally conceived as a calmer, more realistic drama, but grew far more melodramatic and outlandish over time.","wiki_en":"Melrose Place"},{"name":"Muñeca Brava","emoji":"💃","meta":["telenovela","1998–1999","Argentina"],"description":"Milagros, a modest girl from a poor neighbourhood, lands in the world of a wealthy Argentine family, where she runs into scheming and finds real love. The Argentine telenovela, with a young Natalia Oreiro in the lead, became hugely popular far beyond Latin America.","fact":"The show's theme song, sung by Natalia Oreiro, became a genuine hit well outside Argentina.","wiki_en":"Muñeca Brava"},{"name":"The Seven Deadly Sins","emoji":"🍺","meta":["fantasy anime","2014–2021","Japan"],"description":"A band of knights once celebrated and then disgraced, known as the Seven Deadly Sins, comes back together to save the kingdom from a conspiracy and clear their names. Based on Nakaba Suzuki's manga, it mixes adventure fantasy with humour and romance.","fact":"Each of the seven leads is tied to one of the biblical deadly sins, which reflects something in their character.","wiki_en":"The Seven Deadly Sins (TV series)","wiki_ru":"Семь смертных грехов"},{"name":"What We Do in the Shadows","emoji":"🧛","meta":["comedy","2019–2024","USA"],"description":"Four vampire flatmates on Staten Island are filmed for a fake documentary about their eternal but surprisingly dull and domestic immortality. A spin-off of the 2014 New Zealand film of the same name, it kept the original's mockumentary format.","fact":"It is based on the 2014 film by Taika Waititi and Jemaine Clement, who also served as producers on the series.","wiki_en":"What We Do in the Shadows (TV series)"},{"name":"Mighty Morphin Power Rangers","emoji":"🦸","meta":["superhero action","1993–1996","USA"],"description":"Five ordinary teenagers are given the power by an alien mentor to turn into colour-coded superhero Rangers and defend Earth from space villains. It became one of the most recognisable franchises of the nineties by splicing American scenes with Japanese fight footage from Super Sentai.","fact":"The action scenes were cut together from footage of the Japanese series Super Sentai, reworked to fit an American plot.","wiki_en":"Mighty Morphin Power Rangers"},{"name":"Univer. Novaya Obshchaga","emoji":"🛏️","meta":["sitcom","2011–2018","Russia"],"description":"This spin-off of Univer moves the viewer into a student hall of residence, where a new generation of characters works through the comic situations of student life and student relationships. One of the longest-running flagship sitcoms on the TNT channel.","fact":"It continues the earlier series Univer, whose events took place several years before.","wiki_en":"Univer. Novaya Obshchaga","wiki_ru":"Универ. Новая общага"},{"name":"Domashny Arest","emoji":"🏠","meta":["satirical comedy","2018","Russia"],"description":"A young provincial blogger accidentally triggers a political scandal with a blunt video about local corruption, and ends up under house arrest, from where he watches officials react with mounting absurdity. Political satire crossed with situation comedy.","fact":"It came out on a streaming platform and is known for political satire unusually sharp for Russian television.","wiki_en":"Domashny Arest","wiki_ru":"Домашний арест (телесериал)"},{"name":"Zvonite DiCaprio!","emoji":"📱","meta":["drama","2018","Russia"],"description":"A young actor who has just stepped into success learns that he is HIV positive, and has to rethink his relationship with his career, the people close to him and himself. This Russian miniseries was one of the first on national television to treat living with HIV openly and without stigma.","fact":"It was praised for handling the subject of HIV with a delicacy and lack of judgement rare on Russian television.","wiki_en":"Zvonite DiCaprio!","wiki_ru":"Звоните ДиКаприо!"},{"name":"Chiki","emoji":"👭","meta":["drama","2018–2021","Ukraine / Russia"],"description":"The series shows the lives of a group of women in a correctional colony: their friendships, their conflicts and their attempts to hold on to themselves in harsh confinement. A production for the streaming platform Start, it was noticed for an honest, unvarnished look at a women's prison.","fact":"For the sake of accuracy, the production consulted people who knew the real workings of correctional institutions.","wiki_en":"Chiki (TV series)","wiki_ru":"Чики (телесериал)"},{"name":"Emily in Paris","emoji":"🥐","meta":["romantic comedy","since 2020","USA"],"description":"American marketing specialist Emily Cooper unexpectedly moves to Paris for work and tries to reconcile French elegance with American professional zeal, going through a string of romantic entanglements along the way. The Netflix series is known for its bright look and its heroine's wardrobe.","fact":"It is filmed mostly in real, recognisable Paris locations, which has become part of its visual appeal.","wiki_en":"Emily in Paris"},{"name":"Hawaii Five-0","emoji":"🌺","meta":["crime drama","2010–2020","USA"],"description":"A special Hawaii state police unit led by detective Steve McGarrett works the island's hardest cases, from smuggling to terrorism. The modern series is a reboot of the crime show of the same name from the late sixties, and it kept the familiar titles and theme tune.","fact":"The theme music, inherited almost unchanged from the original 1968 show, counts as one of the most recognisable in television history.","wiki_en":"Hawaii Five-0 (2010 TV series)"},{"name":"CSI: NY","emoji":"🗽","meta":["crime drama","2004–2013","USA"],"description":"Another spin-off of the original CSI moves a forensics team to New York, where the investigations are led by detective Mac Taylor, a survivor of the September 11 attacks. It kept the franchise format and added New York colour and a more personal drama for its lead.","fact":"The lead character's backstory involves the loss of his wife in the attacks of 11 September 2001.","wiki_en":"CSI: NY"},{"name":"Murder, She Wrote","emoji":"✍️","meta":["detective","1984–1996","USA"],"description":"Jessica Fletcher, crime novelist and amateur sleuth, finds herself near the scene of a crime in her quiet town with remarkable regularity, and solves it faster than the professional police. One of the longest-running detective series on American television in the eighties and nineties.","fact":"For all her genial manner, across the show's run she witnessed several hundred murders — a paradox viewers never stopped joking about.","wiki_en":"Murder, She Wrote","wiki_ru":"Она написала убийство"},{"name":"MacGyver","emoji":"🧰","meta":["adventure action","1985–1992","USA"],"description":"Secret agent Angus MacGyver gets out of the most dangerous situations not by force of arms but by ingenuity, assembling cunning devices out of whatever happens to be lying around. The character turned his own name into shorthand for the resourceful improvised fix.","fact":"His surname became the verb \"to macgyver\": to solve a problem inventively with whatever is at hand.","wiki_en":"MacGyver (1985 TV series)"},{"name":"Miami Vice","emoji":"🌴","meta":["crime drama","1984–1990","USA"],"description":"Two undercover detectives in sunny Miami investigate the drug trade and organised crime, combining dangerous work with the loud visual style of the eighties: pastel suits and very fast speedboats. The series did much to define the look of a whole decade on television.","fact":"Its trademark look — pastel suits worn without socks, and neon everywhere — had a noticeable influence on eighties fashion.","wiki_en":"Miami Vice"},{"name":"Xena: Warrior Princess","emoji":"🗡️","meta":["fantasy action","1995–2001","USA"],"description":"Xena, a former warlord with a dark past, wanders a mythological ancient Greece with her loyal companion Gabrielle, fighting to atone for what she once did. One of the landmark syndicated shows of the nineties, and a cult figure of popular culture for generations of women viewers.","fact":"Xena first appeared as a supporting character in Hercules: The Legendary Journeys, before she was given a show of her own.","wiki_en":"Xena: Warrior Princess"}];
